INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54005030917', 'Aroma Automotivo Carro Cold Black Vonixx', 'Aromatizante Automotivo Cold Black Vonixx – Fragrância Intensa e Moderna O Aroma Cold Black da Vonixx possui uma fragrância intensa, moderna e marcante, ideal para quem prefere aromas mais fortes e sofisticados, trazendo personalidade ao interior do veículo. Produzido em papel de celulose com essência de alta qualidade, libera o aroma de forma gradual, garantindo perfumação contínua por até 7 semanas, quando utilizado corretamente. Além do uso automotivo, pode ser utilizado em diversos ambientes internos, mantendo o perfume por mais tempo. Modo de uso: Remova o plástico lentamente para controlar a intensidade do perfume e prolongar a duração da fragrância. Características: Fragrância: Cold Black Produzido em papel de celulose Essência premium de alta qualidade Liberação gradual do aroma Duração de até 7 semanas Aroma intenso e sofisticado Precauções: Manter fora do alcance de crianças e animais domésticos. Não ingerir. Em caso de contato com os olhos ou pele, lavar imediatamente com água em abundância.', 32.49, 26.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjr3v17l6c5f71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F712881035%2F54005030917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
