INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494182933', 'Espatula para pintor profissional inox cabo emborrachado 50mm - Decor Colors', 'A Espátula Profissional Inox com Cabo Emborrachado da Decor Colors foi desenvolvida para oferecer o equilíbrio ideal entre resistência e ergonomia, atendendo às demandas de pintores, aplicadores e profissionais que buscam acabamento de alto padrão com conforto no manuseio. 📏 Indicações de uso Aplicação de massa corrida, texturas e gesso Correção de imperfeições e nivelamento de superfícies Raspagem de tintas, adesivos e resíduos diversos Trabalhos em paredes, tetos, cantos e rodapés Uso profissional em obras, reformas e acabamentos finos 🌟 Benefícios e diferenciais Lâmina em aço inoxidável: mais durabilidade, flexibilidade e resistência à corrosão Cabo emborrachado ergonômico: firmeza, conforto e segurança durante o uso Acabamento polido: aplicação limpa e uniforme, sem marcas indesejadas Alta resistência ao desgaste: ideal para uso contínuo em ambientes exigentes Fácil de limpar: ideal para uso com massas, gesso, tintas e produtos químicos Desempenho profissional: resultado superior em aplicações e acabamentos A Espátula Profissional Inox com Cabo Emborrachado da Decor Colors é sinônimo de eficiência, conforto e durabilidade, atendendo com excelência às exigências do trabalho profissional. Uma ferramenta que faz diferença no resultado final, com a qualidade que só a Decor Colors entrega.', 32.99, 31.34, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7ra1a-mbh22r5u2hxy3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1469887994%2F22494182933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
