INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56808140000', 'Conjunto Feminino Infantil Faça Acontecer', 'Conjunto Feminino Infantil Faça Acontecer Conjunto em moletom 100% algodão muito quentinho. Casaco azul marinho com estampa frontal e calça em rosa com detalhe lateral em glitter. Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado.', 69.9, 39.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-81zwi-mmkdw5i9akncb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F56808140000', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
