INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693157993', 'Cama Box Baú + Colchão de Molas Ensacadas Classic Molas Pocket Solteiro 88cm', 'Pensando em melhorar suas noites de sono? A cama Box + Colchão Classic Molas Pocket é a escolha ideal! Fabricado com matéria-prima de qualidade, ele suporta até 120kg por pessoa, proporcionando conforto médio, o que lhe confere conforto extra durante o sono sem comprometer sua coluna. Base baú é confeccionada com madeira de reflorestamento com tratamentos anticupim e antimofo, o seu diferencial é seu compartimento interno garantindo um novo espaço em seu quarto, agregando um valor e sofisticação ao ambiente. Especificações Técnicas Baú: - Marca: Lucas Home; - Material: Madeira tratada; - Peso máximo recomendado: até 150Kg (por pessoa); - Altura do baú: 37cm; - Profundidade do baú: 27cm; - Altura dos pés: 5cm; - Revestimento da Cama: Suede; - Garantia: 12 meses de garantia; - Dimensões do produto (largura x comprimento x altura) 88x188x42cm. Especificações Técnicas Colchão: - Tipo de Mola: Ensacada; - Proteções: Antiácaro - Antialérgico - Antifungo - Antimofo; - Acabamento: Bordado em Matelassê; - Matéria-prima: Espuma/Molas/Tecido; - Tipo de conforto: Macio; - Peso máximo recomendado: até 120kg (por pessoa); - Garantia: 12 meses; - Dimensões do produto (largura x comprimento x altura) 88x188x22cm; Importante: As cores podem variar conforme a tela; Não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Devoluções de produtos íntimos só com embalagem intacta. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 1747.9, 1426.7, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820mb-mn31dva067lu2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208859337%2F22693157993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
