INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259715639', 'Deo Parfum Natura Ilía 50ml', 'Uma fragrância floral envolvente e feminina para inspirar mulheres de atitude Ilía Feminino é uma fragrância que exalta a força e a delicadeza da mulher. combinando notas florais e amadeiradas, esta fragrância traduz a essência de uma feminilidade autêntica e elegante. BENEFÍCIOS: fragrância que combina delicadeza e força. perfumação intensa e duradoura. ideal para ocasiões especiais e uso diário. GOTA OLFATIVA: concentração: deo parfum família olfativa: floral notas de topo: frutas vermelhas, pomelo rosa, flor delaranjeira e bergamota. notas de corpo: flores brancas, muguet, jasmim transparente, gardênia, frésia, rosa. notas de fundo: vanilla, fava tonka, âmbar e musk. cruelty free vegano ocasião: para sair, ocasiões especiais subfamília: adocicado DICAS DE USO: Todo mundo tem um jeito único de se perfumar. mas se você deseja aproveitar todo o potencial dessa fragrância, aplique em áreas como o punho, pescoço e atrás das orelhas. PRECAUÇÃO: Não armazene ou utilize o produto próximo à fonte de calor. Proteja os olhos durante a aplicação. mantenha fora do alcance de crianças. Não aplicar sobre a pele irritada. Evite contato com os olhos. uso externo.', 199.9, 199.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-820no-mnki6dk135l1d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58259715639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18796891516', 'Volante Esportivo Gti Grafite Emblema Logo Vermelho Itália Palio Siena Strada Punto Stilo', '"ESPECIFICAÇÃO TÉCNICA • Diâmetro de 370mm; • Profundidade de 120mm. MODELOS COMPATÍVEIS • CV109 • Uno Fire • Mile • Palio • Marea • Brava • Idea • Siena • Strada • Punto • Stilo • Ducato • Toro • Doblô 2001 em diante Caso não tenha encontrado o modelo do seu veículo neste anúncio, nos consulte. IMPORTANTE • Garantia de 3 Meses; • Somos FABRICANTES ESPECIALIZADOS no segmento automotivo, seguimos um processo rigoroso de fabricação e qualidade; • Entrega ágil e rápida após sua compra; • Enviamos todos os nossos volantes com CUBO ADAPTADOR; • Após a instalação, perde-se a função AIRBAG; • RECOMENDAMOS QUE A INSTALAÇÃO SEJA FEITA POR PROFISSIONAL ESPECIALIZADO. • Fabricamos volantes em POLIURETANO RESISTENTE; • Nossos volantes possuem similaridade ao original com acabamento texturizado e acionamento da buzina. APÓS A COMPRA INFORMAR ANO E MODELO DO VEÍCULO EM NOSSO CHAT. Sua satisfação é nossa maior recompensa! Estamos à disposição e teremos o imenso prazer em atendê-lo!"', 212.49, 170.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134201-820lp-mp9j53j21m2u51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954535653%2F18796891516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798008017', 'Volante Esportivo Renault Sandero Logan Clio Duster Scenic', 'Oferecemos durabilidade e resistência incomparáveis. O volante T-Cross foi projetado para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 370mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Renault Clio 1998 À 2014 • Renault Sandero 2007 Em Diante • Renault Logan 2007 Em Diante • Renault Scenic 1999 À 2016 • Renault Megane 2002 À 2016 • Renault Kangoo 2001 À 2020 • Renault Duster 2016 EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes', 399.98, 199.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7reoe-m272b5m345oca5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954535653%2F2