INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693908939', 'Importway Guarda Sol Articulado Praia Grande 2,4 M Pesca Praia Azul Listrado', 'Guarda Sol 2,40m Articulado Material De Nylon Importway O Guarda Sol Articulado da Importway irá te acompanhar nos melhores momentos do verão, você poderá levar ele para o camping, piscina, praia, todos lugares que precisará daquela sombra aconchegante. Especificações: • Marca: Importway • Modelo: IWGSA24006 • Guarda sol com 2,40m de diâmetro • Topo articulado • Diâmetro da haste 32mm • Haste em aço inoxidável • Tecido de nylon Conteúdo da Embalagem: - 01 Guarda Sol 2,40m Articulado Material De Nylon Listra Azul Importway "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 110.04, 89.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Umbrellas', 'https://cf.shopee.com.br/file/sg-11134201-7repu-m8fmh29g9juod0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229255557%2F22693908939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
