INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498106300', '101 curiosidades - Brasil', 'O Brasil é famoso pelas suas belezas naturais, pela música e também pelo futebol. Mas há muitos outros fatos que tornam o país um dos mais magníficos do mundo. Vire as páginas e prepare-se para descobrir incríveis curiosidades sobre o Brasil, como suas origens, seus recordes, seus conflitos, suas principais personalidade e muito mais! 14x21cm 32 Páginas', 11.95, 7.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7ra3v-m4gnn22ewdms47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23498106300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
