INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12019355993', 'Kit 10 Cuecas Boxer Algodão c/ Poliéster C5 + 3 Pares de Meias', 'Cueca Boxer C5 é uma ótima cueca masculina de entrada (mais popular) Essas cuecas boxer são confeccionadas em algodão (Cotton) com poliéster e elastano, tecido leve e macio, desenvolvido especialmente para quem não abre mão do conforto e busca preço. Modelagem boxer com formato anatômico que proporciona total aderência, e se adapta perfeitamente ao corpo. Composição: 50% Algodão 45% Poliéster 5% Elastano Tamanhos: P (36-38) M (40-42) G (44-46) GG (48-50) O Kit é enviado de forma sortida, podendo haver repetição de cores. SOBRE A COMPRA MAIS: A Compramais tem como missão desde 2013 proporcionar satisfação e qualidade para clientes em todo o Brasil. Trabalhamos com agilidade para garantir que seu pacote chegue com rapidez em suas mãos, no conforto do seu lar e sem precisar sair de casa! Temos um catálogo extenso de moda íntima que conta com itens femininos, masculinos e infantis. Ainda tem alguma dúvida? Nos faça uma pergunta! Compramais, paixão em moda íntima.', 149.9, 149.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-23020-pggomnft9hnvbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F12019355993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
