INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298837075', 'Fecho Do Cinto De Segurança Traseiro Parte Femea Universal X', 'Fecho Do Cinto De Segurança Traseiro Parte Femea Universal Itens Inclusos: 1 FECHO FEMEA. Produto com foco em qualidade, resistência e durabilidade para uso automotivo. Para melhor desempenho, recomenda-se instalação por profissional qualificado. Características: Materiais dos componentes: Poliéster, Aço carbono temperado e ABS. 1 anos de garantia. Benefícios do uso do cinto de segurança: Reduz o risco de ferimentos graves em acidentes de trânsito. Mantém o corpo estabilizado, evitando o impacto contra o volante ou painel. Garante segurança e conforto durante a condução. Atende às normas de segurança veicular exigidas por lei. Evita multas e pontuação na CNH por uso incorreto. Indicado para todos os veículos: carros, caminhonetes e utilitários. Fácil instalação e reposição, ideal para manutenção preventiva. Custo-benefício alto, sendo essencial para a segurança automotiva. Recomendações: - Instalar com apoio de profissional qualificado. - Garantia de 6 meses.', 19.72, 19.72, NULL, 'Mom & Baby > Baby Travel Essentials > Car & Motorbike Seats Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdxo-mdfn4eh5ig9wb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1604698269%2F22298837075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22225826970', 'Ração Úmida Royal Canin Veterinary Renal Cães Adultos 410g', 'Ração Úmida Royal Canin Veterinary Renal Cães Adultos 410g - Indicado para cães; - Para cães adultos com doenças renais; - Ajuda a estimular o apetite do cão; - Formulado com baixo nível de fósforo; A Ração Úmida Royal Canin Renal Cães Adultos coadjuvante indicada para cães adultos com doenças renais. Formulada para ajudar a dar suporte à função renal em casos de doença renal crônica ou lesão renal aguda.Esta dieta é formulada com um baixo teor em fósforo e fornece uma quantidade moderada de proteínas de alta qualidade, para ajudar a apoiar a função renal. Para ajudar a estimular o apetite, esta dieta é formulada com um perfil aromático específico e tem uma textura especial. Consulte sempre o Médico veterinário.', 45.9, 43.61, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-23020-ldfaf542xrnv2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F22225826970', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
