INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17888601118', 'L''Oréal Professionnel Serie Expert Vitamino Color Máscara 250ml', 'A Máscara de Tratamento Vitamino Color Foi Desenvolvido Especialmente Para Cabelos Coloridos, Pois Ela Promove a Proteção Até Das Cores Mais Sensíveis, Hidratação e Luminosidade Para Os Fios. Além Disso, Seu Principal Ingrediente Possui Um Poderoso Antioxidante Presente Na Casca e Nas Sementes Das Uvas, Que Tem a Função de Preservar a Cor Dos Cabelos.', 248.9, 248.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22100-9yeb7104k7iv02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F17888601118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43614519444', 'Creme de Tratamento Cachos dos Sonhos L''Oréal Paris 300g', 'Nosso Creme de Tratamento Nutritivo proporciona uma transformação para fios visivelmente saudáveis, com uma ação imediata na fibra capilar. Nossa fórmula preenche o cabelo com nutrição profunda até as pontas, para cachos mais fortes e definidos desde o primeiro uso. Seu aliado para tratar e selar os fios até as pontas para salvar até os últimos 3cm dos seus cachos.', 42.9, 38.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdq2wn73ikl59c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F43614519444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28088353035', 'Shampoo Nutrição Óleo Extraordinário Elseve L''Oréal Paris 200ml', 'SHAMPOO NUTRIÇÃO ÓLEO EXTRAORDINÁRIO ELSEVE 200ML Um cabelo seco parece estar sem vida, pois ele está opaco, sem brilho e tem um toque áspero. O segredo dos óleos de flores preciosas para uma nutrição perfeita & uma leveza infinita estão na linha Elseve Óleo Extraordinário Nutrição. O Elseve Óleo Extraordinário Nutrição com sua textura ultrafina e leve, é enriquecido em Micro-Óleos de Flores Preciosas que agem para combater o cabelo seco e sem brilho. Reconstrói a fibra, fazendo com que seu cabelo tenha uma nutrição perfeita, leveza infinita e um brilho excepcional. Resultado Os cabelos secos ficam cheios de vida e sem pesar. Sublimes em todos os ângulos. Modo de Uso Aplique o shampoo nos cabelos molhados e massageie suavemente. Enxágue. Repita a operação se necessário.', 29.9, 25.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbsj0ji0obbt8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F28088353035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
