INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598326606', 'Tênis Red Nose Cobble Branco/Marinho Adulto', 'Tênis Red Nose: Estilo e Versatilidade para o Dia a Dia O Tênis Red Nose é a escolha ideal para quem busca conforto e praticidade sem abrir mão do estilo. Com design moderno e materiais de alta qualidade, ele oferece uma experiência de uso única. Conforto e Ajuste Perfeito: Projetado para o dia a dia, proporciona leveza e se ajusta bem ao formato dos pés. Versatilidade: Perfeito para diversas ocasiões, combina facilmente com jeans, bermudas ou calças casuais. Durabilidade e Estilo Casual: Material resistente que alia durabilidade e um visual estiloso. Numeração: Disponível do 37 ao 44, atendendo a diferentes perfis e estilos. Composição: Confeccionado em materiais leves e resistentes para máxima qualidade.', 239.9, 215.91, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7iibxqld50yd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1054730940%2F22598326606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
