INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497182155', 'A Incrível Bíblia | Ellen Pestili', 'Uma Incrível Bíblia para despertar a criatividade e o amor pela Palavra. A Bíblia Sagrada é o livro mais lido da história, mas sua leitura pode ser desafiadora tanto para os grandinhos como para os baixinhos.A Incrível Bíblia une um texto de fácil leitura e fiel aos escritos originais com deslumbrantes ilustrações, tornando o encontro com as Escrituras um momento lúdico e prazeroso. O livro contém 45 histórias contadas de forma envolvente e educativa, transmitindo valores essenciais como amor, respeito e esperança. Além disso, elas são ricamente ilustradas pela autora e artista plástica Ellen Pestili, com imagens artesanais de variados estilos que transformam cada página em uma experiência sensorial única. 28x22cm 304 Páginas', 90.9, 85.45, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbk4-lpcjpvzgws8jbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23497182155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
