INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50700608886', 'Kimmon, Selva dos Sonhos Boneco Pelúcia Colecionável Surpresa 20cm', 'A fusão entre arte e fofura em mini pelúcias que também funcionam como acessórios para bolsas e mochilas. Cada personagem apresenta design excêntrico, expressões marcantes e roupas cheias de detalhes que evocam um universo mágico e enigmático. A textura macia contrasta com a intensidade das cores e acabamentos criativos, tornando cada peça um destaque de estilo. A embalagem surpresa adiciona ainda mais mistério, revelando protagonistas diferentes que carregam consigo charme, originalidade e personalidade única. Inspirada na natureza selvagem, essa série mistura elementos da floresta e do mundo animal em pelúcias-acessórios únicos. São 6 modelos principais e 1 versão rara, revelado apenas no unboxing surpresa, evocando a magia de aventuras ao ar livre.', 199.99, 187.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-821ej-mgi2dx1kbw96b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F50700608886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197562571', 'Rolamento Roda Dianteiro Snr New Civic G8 2006 2007 2008 2009 2010 2011', 'Seja Bem-vindo(a)! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa Loja. Produtos: 01 Rolamento de Roda Dianteira Veiculos com ABS Marcas: SNR Aplicação: New Civic G8 16V 2006 até 2011 Garantia 90 dias. É novo, e acompanha nota fiscal? Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. - ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 198.7, 198.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rd6e-lwhgei0h2daj3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F23197562571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898194611', 'Fantasia de Bombeiro com Acessórios - Melissa & Doug', 'Descrição: "Conjunto de vestir e brincar com tudo que uma criança precisa para ter uma aparência adequada, além de acessórios emocionantes para estimular brincadeiras imaginativasInclui jaqueta, capacete, distintivo, extintor de incêndio, megafone e etiqueta de nome reutilizávelMegafone faz efeitos sonorosMateriais de alta qualidade garantem durabilidade e segurançaDimensionado para idades de 3 a 5 anos" Características: Marca: Sunny Brinquedos Referência: 4632 Idade recomendada: A partir de 4 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não. Necessita 2 pilhas AA (LR6) de 1,5V Possui Luzes: Não Possui Sons: Sim Dimensões aproximadas da embalagem: 50 x 40,5 x 18cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: Jaqueta, Capacete, Distintivo, Extintor, Megafone, Etiqueta de Nome Reutilizável Certificado Inmetro: REGISTRO 015488/2024 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 499.99, 399.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rce9-m65yeb2c5lsn69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23898194611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
