INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097702386', 'Spray de Silicone Walther PRO Gun Care Airsoft & Airguns - 200ml', 'Spray de Silicone Walther PRO Gun Care Airsoft & Airguns - 200ml O Spray de Silicone Walther Pro foi projetado para a manutenção e o cuidado de armas de pressão e airsofts. É um lubrificante de alto desempenho, ideal para parafusos, conexões, válvulas, dobradiças, guias, mancais, juntas, acoplamentos, hop up, podendo ser utilizado inclusive em armas de fogo. O spray de silicone de 200 ml reduz a fricção, mantém as partes móveis flexíveis e adere muito bem à superfície. Como resultado, é duradouro e econômico, não há necessidade de reaplicação contínua. Pode ser usado em temperaturas de -70ºC a + 250ºC. Fabricado na alemanha com todo padrão Europeu para total desempenho de sua arma. CARACTERÍSTICAS: - Fabricante: Walther / Alemanha - Modelo: Pro Gun Care - Aplicação: Aerossol - Conteúdo: 200ml - Aplicação: Lubrificação de Armas de Fogo, Airsoft, Airguns e demais mecanismos e ferragens. FOTO MERAMENTE ILUSTRATIVA', 32.89, 32.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-m03sxjcsv9xc1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654132276%2F22097702386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499246191', 'Filtro Gasolina PAMPA 1981/1997 - 43699 - FCC225', 'Filtro Gasolina PAMPA 1981/1997 MOTOR 1.6 CHT/1.8 AP ÁLC/GAS (GRANDE BICO 6/8mm) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 18.7, 18.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822y4-mo9qimy5a5n258', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19499246191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798076327', 'Cilindro Roda Ford Mondeo 1994 a 2001 - 151971 - CCR9270', 'Cilindro Roda Ford Mondeo 1994 a 2001 151971 CCR9270 TRASEIRO ESQ/DIR MODELO SW (7/8" OU 22,22mm - SISTEMA VARGA)O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 63.54, 63.54, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd4t-m7u6d8xv9ams91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23798076327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093508991', 'Reservatório Óleo Freio Vw Saveiro 1998 a 2009 - 134285 - C0102', 'Reservatório Óleo Freio Vw Saveiro 1998 a 2009 134285 C0102 MOD. G2/G3/G4 (COM TAMPA e AVISO DE NÍVEL - S/ABS) O reservatório de fluído de freio pode ser incorporado ao corpo, ou separado, feito em material plástico, translucido para observação do nível o de fluído do sistema. A tampa do reservatório possui um orifício que põe o fluído em contato com a pressão atmosférica, o que impede que se crie “vácuo” durante o funcionamento dos freios. Além disso, esta possui um interruptor elétrico que informa ao motorista, através de uma lâmpada piloto no painel, quando o nível de fluído de freio diminui.', 98.27, 98.27, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-lmqhaj0pgah1ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22093508991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498186481', '2 Par Pastilha Freio Disco Shimano Mt200 Tektro Winzip Gta', 'ATENÇAO PARA NAO HAVER ERRO NA COMPRA TIRE SUAS PASTILHAS E COMPARE COM AS FOTOS Compatível com conjunto de freio série Auriga Comp / Auriga E-comp / Aquila / Draco / Shimano / GTS / GTA Marca : GTS Tipo : Semi Metálica Tamanho total da pastilha (Bandeja) 31mm Espessura da bandeja 1,7mm Espessura da pastilha 2,1mm Espessura total (Bandeja + Pastilha) 3,8mm Mais silenciosa Frenagens prolongadas Menor agressividade contra os discos Aquecem menos favorecendo frenagens prolongadas Maior eficiência em frenagens leves Peso aproximado: 20g Compátivel com modelos: Deore BR-M515 M515-M M515-LA M525 ACERA BR-M415 ALIVIO BR 465/466 M-475 M-315 M-485 M-495 MT200 WINZIP GTA NEXAVE C-501 NEXAVE C-601 TEKTRO DRACO-2 TEKTRO AURIGA TEKTRO AURIGA COMP HYD AQUILA RST D-POWER GTS HIDRAULICO PREÇO REFERENTE A 2 PARES DE PASTILHA (4 LADOS )', 22.3, 22.3, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7ravo-mactekzg2j4h73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F21498186481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
