INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998046474', 'Filtro Ar Ford Ranger 2011 a 2016 - 186497 - WR191', 'Filtro Ar Ford Ranger 2011 a 2016 186497 WR191 (Wildtrack / XL / XLS) - Motor 3.2 20v Diesel - (Automático) - Filtro de ar do motor Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 116.49, 116.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbl4-lnrn30n1rxum7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23998046474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4193986815', 'Movimento Central Absolute 08A 113.5 mm', 'Movimento central Absolute rolamentado selado compatível com quadros com o padrão 34.7 mm. Este modelo é compatível com pedivelas padrão ponta quadrada. Especificações: - Comprimento do eixo 113,5 mm; - Comprimento do corpo 68-73 mm; - Compatível com quadros padrão rosca 34.7 mm (os mais comuns); - Compatível com pedivelas ponta quadrada; - Acompanha 2 parafusos de fixação sextavados.', 25.86, 25.86, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/52ca57ddd907b6569fd76a4d543021de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F4193986815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598243981', 'MANGUEIRA RESPIRO ÓLEO FOX 2003/2016 - 89180 - 4203', 'MANGUEIRA RESPIRO ÓLEO FOX 2003/2016 Respiro do Óleo ao Antichama 1.6 FLEX (Ø:15mm 9/16 ")(Medida:25cm x 49cm)Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 50.3, 50.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-m6uq4jkpppu46d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23598243981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
