INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21232428240', 'Isolante Térmico Aluminizado Em EVA - Nautika', 'Isolante Térmico Aluminizado em Eva - Nautika O isolante térmico aluminizado em EVA NTK é o modelo perfeito para tornar as suas noites de camping ainda mais divertidas e agradáveis. O produto é super leve, atóxico e sem cheiro. É laminado em alumínio refletivo para máximo isolamento térmico, fundamental para você não tenha problemas na hora de dormir. Pesa 200 g, tem medidas de 180 cm (A) x 50 cm (L) x 6 mm (P), modelo solteiro, conta com 2 elásticos para melhor compactação no transporte e armazenamento e está disponível na cor preta. Pesa 200 g, tem medidas de 180 cm (A) x 50 cm (L) x 6 mm (P), modelo solteiro, conta com 2 elásticos para melhor compactação no transporte e armazenamento e está disponível na cor preta. Características: - Marca: Nautika - Modelo: Isolante Termico - Material: Eva laminado - DImensões: 1,80m x 50cm x 6mm - Cor: Preto - Peso: 200g Itens Inclusos: - 1x Isolante térmico - 1x Nota fiscal', 71.01, 63.91, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/33b73fe373e6ac987cf74da974b55eda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F618731843%2F21232428240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
