INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44756026873', 'Paulo o pastor | Scot McKnight', 'Scot McKnight é professor de Novo Testamento no Northern Seminary, em Lisle, Illinois. Reconhecido mundialmente como estudioso, autor e palestrante, já escreveu, coescreveu ou editou mais de 75 livros, entre eles It Takes a Church to Baptize, Adam and the Genome, Kingdom Conspiracy, The Jesus Creed, The King Jesus Gospel e The Apostle Paul and the Christian Life. McKnight também atua como teólogo canônico na Diocese of Churches for the Sake of Others. Detalhes do produto: Autor: Scot McKnight Editora: Vida Acabamento: Brochura Formato: 16 larg. X 23 alt. Número de Páginas: 328', 58.9, 58.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262b-mki701pn3htv75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F44756026873', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52805025498', '52 Reflexões Como parar de se preocupar e começar a viver | Dale Carnegie', '52 Reflexões Como parar de se preocupar e começar a viver | Dale Carnegie A PREOCUPAÇÃO É UMA LADRA SILENCIOSA DE ENERGIA, SONO E ALEGRIA. Inspirado no clássico de Dale Carnegie, este livro apresenta 52 reflexões para libertar a mente do excesso de ansiedade e reencontrar o equilíbrio interior. Com uma leitura simples e transformadora, Sam Buttler adapta os princípios de Carnegie à vida moderna: viver um dia de cada vez, aceitar o inevitável, cultivar fé, gratidão e coragem diante das incertezas. A vida acontece hoje. Escolha viver o presente com leveza e propósito. Autor: Dale Carnegie Editora: Principis Acabamento: Capa comum Dimensões: 16x23 Número de páginas: 96', 11.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82610-mjr76k3b4sg63f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F52805025498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
