INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41219816062', 'Caixa 15un Refresco Em Pó 15G Laranja Ki-Suco ( Para 1L)', 'O Ki-Suco Laranja oferece um sabor especial e adocicado, super refrescante e prático para toda a família! – Rende 1 litro! – Gostoso e refrescante. – Com Vitamina C. – Com polpa de fruta. – Embalagem divertida com o jarrão sorridente. – Ótimo custo benefício. Açúcar, vitamina C (ácido ascórbico), suco de laranja desidratado, acidulante ácido cítrico, edulcorantes: ciclamato de sódio (25mg/100ml), aspartame (17mg/100ml), acesulfame de potássio (4mg/100ml) e sacarina sódica (3mg/100ml), aromatizante, regulador de acidez citrato de sódio, corante inorgânico dióxido de titânio, antiumectantes: fosfato tricálcico e dióxido de silício, corantes artificiais: tartrazina e amarelo crepúsculo FCF e espessantes: goma xantana e goma guar. NÃO CONTÉM GLÚTEN. CONTÉM FENILALANINA.', 13.56, 13.56, NULL, 'Food & Beverages > Beverages > Powdered Drink Mixes', 'https://cf.shopee.com.br/file/sg-11134201-824jh-met2sns2fyte4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F41219816062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
