INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40311049602', 'Brinco Feminino de Prata 925 Quadrado Cravejado com Zircônia', 'Brinco Feminino de Prata 925 Quadrado Cravejado com Zircônia: Elegância e Brilho O Brinco Feminino de Prata 925 Quadrado Cravejado com Zircônia é a peça ideal para quem busca sofisticação e brilho. Seu design quadrado e moderno, combinado com as zircônias cravejadas, traz um toque de elegância e classe ao seu visual. Feito com Prata 925 de alta qualidade, oferece resistência, brilho duradouro e conforto para o uso diário ou ocasiões especiais. Especificações do Brinco Tamanho: 6mm Peso: 1,18g Material: Prata 925 Destaques do Brinco Design quadrado moderno, cravejado com zircônias, adicionando brilho e elegância ao seu look. Feito com Prata 925 de alta qualidade, garantindo resistência e durabilidade. Leve e confortável, ideal para o uso diário ou para ocasiões especiais. Brilho e Sofisticação para Seu Estilo O Brinco Feminino de Prata 925 Quadrado Cravejado com Zircônia é a escolha perfeita para quem deseja adicionar um toque de brilho e sofisticação ao seu visual. Seu design moderno e elegante é ideal para diversas ocasiões, proporcionando um visual radiante e cheio de classe. Cuidados com o Brinco Evite o contato com produtos químicos para preservar o brilho da prata e das zircônias. Guarde em local seco e seguro para evitar arranhões e oxidação. Limpe regularmente com uma flanela macia para manter o brilho e a beleza do brinco. Adicione Sofisticação e Brilho ao Seu Look Adicione o Brinco Feminino de Prata 925 Quadrado Cravejado com Zircônia à sua coleção e experimente um acessório sofisticado que vai realçar sua beleza e complementar seu estilo com elegância e brilho.', 68.1, 54.48, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcup1m6x85j535', 'https:/