INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21568485571', 'Condicionador Fortalece E Tonifica/ Tonific Baba D''aloe 240g', 'TONIFIC BABA D''ALOE Tonificação e fortalecimento dos cabelos. O Tonific Baba D''Aloe é especialmente utilizado na tonificação e fortalecimento dos cabelos. Ideal para ser usado em conjunto com o Kit Tonific Flores & Vegetais. O kit Tonific, da linha de terapia capilar, Flores e Vegetais, é a clássica associação dos extratos concentrados de aloe vera e ginseng, com um toque de óleo essencial de alecrim para tonificar e fortalecer os cabelos. A clássica associação dos extratos concentrados de aloe vera e ginseng com um toque de óleo essencial de alecrim para tonificar e fortalecer os cabelos. Conselho de aplicação: Aplique o condicionador Baba D''Aloe no couro cabeludo, ainda levemente umedecido, após a lavagem dos cabelos. Massageie lentamente para estimular a melhor absorção do produto e estenda a aplicação para os cabelos. Aguarde por 10 minutos e enxágue. Este produto também pode ser aplicado com o propósito de TERAPIAS NOTURNAS. Aplique após o banho e permaneça com o produto nos cabelos por toda a noite. Somente retire-o na manhã seguinte com a lavagem normal dos cabelos. Quem somos : A Locus é uma loja online, que oferece produtos nacionais e importados no Brasil. , temos orgulho desse sucesso e hoje conquistamos clientes em todo o Brasil, o resultado para nosso sucesso é simples, entregamos exatamente o que prometemos para atender todas as expectativas dos nossos clientes. Servir bem, para servir sempre. Obrigada!!!', 97.12, 97.12, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lowv8kdbu8c23e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353832716%2F21568485571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43221904622', 'Envelope Cards Elo Monsters Enaldinho - Novo - Editora Pixel', 'Envelope Cards Elo Monsters EnaldinhoEste produto contém: 1 Flow pack (5 card sortidos)Uma grande batalha entre os Elo Monsters está para começar, e o grande estrategista da disputa é você! Embarque em um jogo de cards cheio de ação e emoção, no qual 40 monstrinhos entram em campo com os seus atributos para disputar rodadas eletrizantes! Com foco e atenção, analise as principais virtudes dos seus monstros e escolha com sabedoria: força, defesa, velocidade, inteligência ou vigor... uma boa decisão pode garantir a vitória, e a estratégia perfeita pode surpreender o adversário! Simples de jogar, mas com espaço para estratégias inteligentes, o jogo é perfeito para desafiar os amigos e desenvolver inúmeras habilidades.Tipo de Produto: Cards Segmentos: Colecionáveis, Colecionáveis - Entretenimento Marcas: Pixel ISBN: 7898923266305 Editora: Editora Pixel Idioma: Português Condição: Novo/Lacrado', 19.9, 19.9, NULL, 'Hobbies & Collections > Collectible Items > Sports Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-824he-mf5lsfzz2byme5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F43221904622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
