INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799723539', 'Nicho Aéreo Garrafeiro Kappesberg Celeste 100% MDF Branco 15cm', 'Sua cozinha merece toda a beleza e qualidade que a Linha Celeste da Kappesberg oferece. Moderna e com um design único, essa é a cozinha ideal para quem procura unir estilo e sofisticação. Por isso, aposte no Nicho Garrafeiro N752 para deixar seu projeto ainda mais completo. Produzido 100% em MDF de 15mm, o que garante mais robustez, firmeza e qualidade ao produto, ele possui 73,5cm de altura, 15cm de largura e 37cm de profundidade, podendo ser utilizado em todos os projetos. Prático e versátil, ele garante que você organize garrafas e outros itens decorativos, deixando seu espaço lindo. Fechando ótimas combinações com o nicho toalheiro, com até sete camadas de pintura, e seu acabamento brilho na cor branca, além de ser perfeita para a cozinha, garante a sensação de mais luminosidade ao ambiente, além de praticidade na limpeza, deixando sua cozinha completa. Renove sua cozinha e a deixe do jeito que você sempre sonhou com a Cozinha Celeste da Kappesberg. Medidas: • 73,5 cm de altura • 15 cm de largura • 37 cm de profundidade Itens inclusos: • Três (3) divisórias Código do produto: N752-BR Informações importantes: • As imagens são ilustrativas. • A Kappesberg não disponibiliza serviço de montagem (recomendamos a contratação de um profissional qualificado). • O manual de montagem acompanha o produto. • 3 meses de garantia para defeitos de fabricação.', 212.8, 199.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8260y-mlwjwn8n5mh0d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F20799723539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
