INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598788147', 'Calça Jogger Feminina Com Bolsos Marialícia Verde', 'A Calça Marialícia combina estilo e conforto em uma única peça. Confeccionada em moletinho de viscose com elastano, ela possui elástico no cós e nos punhos, trazendo uma modelagem jogger moderna e garantindo um ajuste perfeito. Além disso, os bolsos frontais proporcionam praticidade ao visual. Peça-chave para compor looks para passeios, viagens ou momentos relax, combine com blusas básicas e tênis para um visual comfy!', 199.9, 99.95, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mr1tihzjgzr41b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23598788147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254788829', 'Conjunto Curto Infantil Menino Robô Elian Amarelo', 'Estiloso e divertido, o Conjunto Elian é composto por camiseta em meia malha e bermuda em moletom dublado. A camiseta de mangas curtas possui estampa trazendo o rostinho de um robô e toda a sua anatomia, garantindo um toque de personalidade ao visual. Já a bermuda conta com elástico no cós, etiqueta emborrachada e textura diferenciada. Ideal para explorar a imaginação em momentos de lazer, invista nesse look cheio de estilo para os meninos aproveitarem cada instante!Detalhes da peça: • Conjunto composto por camiseta e bermuda • Feito em meia malha e moletom dublado • Possui mangas curtas • Possui estampa de robô • Possui elástico no cós • Ideal para momentos de lazer', 89.9, 71.92, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8257z-mr1tpk5b1xqc38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58254788829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
