INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7682946959', 'Som Automotivo Com Usb, Bluetooth E Leitor De Cartão Sd', 'Rádio Automotivo Bluetooth FP IMPORTS 4x25W - Exclusivo OESTESOM Compatível com Diversos Sistemas de Som Ideal para quem busca um rádio automotivo completo, com tecnologia avançada e funcionalidades que atendem tanto aos exigentes como aos que buscam praticidade no dia a dia. Potência e Qualidade de Som Este rádio automotivo oferece 4 saídas de 25W cada, garantindo som potente e claro para seu carro. Equipado com equalizador completo (EQ, Bass, Tre, Fad, Ba) e predefinições de som (Classic, Rock, Pop), proporciona a melhor experiência de áudio personalizada. Conectividade Bluetooth e Controle por App Ouça suas músicas favoritas sem fios através do Bluetooth. Controle o rádio diretamente pelo aplicativo no seu celular, proporcionando praticidade e facilidade de uso. Multimídia Completa Além do Bluetooth, o rádio possui entrada USB, leitor de cartão SD e 4 saídas RCA para conexão com amplificadores e subwoofers. Reproduz músicas direto de pastas organizadas, permitindo total controle do conteúdo. Rádio FM Estéreo e Mais Funções Aproveite a função Rádio FM Estéreo e outras funcionalidades como intro, pause, repeat, e controle remoto para uma experiência completa. Carregue seu celular pela porta USB disponível. Display em LED Moderno Com um display em LED, o design moderno e funcional do rádio garante fácil visualização em qualquer condição de luz.', 84.03, 72.03, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6fh8m7vdkjr6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F7682946959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
