INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292098845', 'Barraca 8 Lugares Luna Com Colchão Casal e Bomba De Pé Camping', 'Kit Completo para Acampamento: Barraca Luna MOR (4, 5, 6, 7 ou 8 Pessoas) + Colchão Casal Inflável com Inflador Integrado Tenha mais conforto, praticidade e proteção em suas aventuras com este kit completo para camping! Ideal para famílias, casais ou grupos de amigos, o combo inclui uma Barraca Luna MOR no tamanho de sua escolha (4, 5, 6, 7 ou 8 pessoas) + um resistente Colchão Inflável de Casal com inflador embutido. 🛏️ Itens Inclusos: 1 Barraca Luna MOR (modelo conforme sua escolha) 1 Bolsa de transporte 1 Colchão Inflável Casal MOR com bomba embutida tipo fole 1 Kit de reparo para o colchão 🏕️ Sobre a Barraca Luna MOR: Projetada para oferecer conforto e proteção durante o acampamento, a Barraca Luna conta com sobreteto com tratamento Silver Coating e proteção solar FPS 100, que ajuda a manter o interior mais fresco e protegido contra chuvas leves. Estrutura leve com varetas de fibra de vidro, montagem rápida e mosquiteiros integrados nas portas, teto e janelas. Vantagens: Sobreteto com Silver Coating e proteção solar FPS 100 Coluna d’água de até 800 mm (modelos até Luna 7) ou 1200 mm (Luna 8) Tecido 100% poliéster e piso em polietileno Mosquiteiros nas janelas, teto e portas Gancho interno para lanterna Leve, resistente e fácil de transportar com bolsa inclusa Tamanhos disponíveis (C x L x A): Luna 4: 2,10 x 2,10 x 1,30 m Luna 5: 2,40 x 2,40 x 1,30 m Luna 6: 2,60 x 2,60 x 1,65 m Luna 7: 3,00 x 3,00 x 1,80 m Luna 8: 3,50 x 3,50 x 1,90 m — mais espaçosa e com melhor impermeabilização 🛌 Sobre o Colchão Inflável Casal MOR: Perfeito para noites de sono mais confortáveis no camping! Fabricado em vinil pré-testado e com revestimento aveludado, o colchão é resistente e acompanha inflador embutido tipo fole, que permite inflar com facilidade usando o pé. Características: Medidas: 1,91m x 1,37m x 22cm Peso: 3 kg Suporta até 160 kg Revestimento aveludado e superfície confortável Inflador embutido com mola (infla mais rápido) Acompanha kit para reparo 🚚 Envio Rápido | Produto Original com Garantia | Pronto para suas Aventuras! Escolha o modelo ideal e aproveite sua próxima aventura com muito mais conforto e tranquilidade. Ideal para campings, praias, trilhas ou como cama extra em casa.', 548.98, 469.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbh0duz69f20d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F23292098845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
