INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397444283', 'Conector para trilho de Spot Trilho nas cores Branco e Preto', '✨ Conector para Trilho - Conectividade Versátil para Iluminação Personalizada ✨ O Conector para Trilho oferece uma solução simples e eficaz para conectar diferentes componentes em sistemas de trilhos de iluminação. Disponível nas cores branca e preta, este conector combina perfeitamente com qualquer estilo de decoração. 🔌 Características: Código: Conector para Trilho Cor do Material: Disponível em Branco ou Preto Com este conector, você tem a liberdade de criar configurações de iluminação personalizadas e adaptáveis às suas necessidades. Seja para iluminar ambientes residenciais ou comerciais, este acessório versátil garante praticidade e elegância em qualquer projeto de iluminação.', 16.0, 13.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rcf4-ltqskqm1559446', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F22397444283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892254301', 'Flange Bomba Combustivel Palio 96 97 98 99 00 01 Tsa - 38731 - T030024', 'Flange Bomba Combustivel Palio 96 97 98 99 00 01 Tsa MOTOR 1.0/1.5/1.6 16V GAS (Engate Rápido) (MARWAL) Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 41.61, 41.61, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822z0-mofgmsp2olc0e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23892254301', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897462785', 'Pré Filtro Combustível Hyundai Tucson 2005 a 2011 - 516014 - 1344', 'Pré Filtro Combustível Hyundai Tucson 2005 a 2011 516014 1344 Motor 2.0 16v O pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada._x000D_ Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento._x000D_ Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 33.43, 33.43, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd3s-luf65t4sdpub5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23897462785', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
