INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19577230808', 'Piscina Playground Arco Iris 246 Litros - Intex', 'Piscina Playground Arco-Iris 246 Litros - Intex Faça com que a diversão dos mais novos se multiplique com este centro de jogos aquático inflável da Intex" A Piscina Playground Arco-Iris é um centro de jogo de água dividido em duas piscinas e que inclui diferentes acessórios para poder brincar com eles enquanto os pequenos dão um mergulho refrescante. Vem com borrifador de água, conecta-se à mangueira de jardim para manter as crianças refrescadas no verão, tem plugues de drenagem no fundo das piscinas, acompanha Kit de reparo e é muito fácil de inflar. Conta com um escorrega com base acolchoada para amortecer a queda e aros infláveis encaixáveis. Possui tampão de escoamento para facilitar ao encher e esvaziar. Com 6 bolas de polietileno branco e 4 aros infláveis para encaixar. Idade recomendada: Acima de 3 anos. Informações Técnicas: - Medidas: 297 x 193 x 135 cm - Capacidade: parte grande com 227L e pequena com 20L - Fabricada em vinil extra resistente', 507.99, 507.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7qvfv-lezs7he67nfc62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19577230808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797299539', 'Fisher-Price Controle Remoto Irmã do Cachorrinho - Mattel', 'Fisher-Price Controle Remoto Irmã do CachorrinhoO Fisher-Price Controle Remoto Irmã do Cachorrinho da Mattel é um brinquedo inovador que simula um controle remoto de TV, porém com recursos divertidos e educativos para os pequenos. Ao pressionar os botões, a tela ilumina, enquanto músicas e frases estimulantes apresentam números, letras do alfabeto, opostos e muito mais. Esse brinquedo auxilia no desenvolvimento das habilidades motoras finas, como destreza e coordenação olho-mão, além de proporcionar uma brincadeira de faz de conta envolvente. Idade recomendada: A partir de 6 meses. Selo Inmetro: 00128-06A. Diferenciais:Design atrativo e intuitivo que simula um controle remoto de TV para adultos. Botões iluminados que ativam sons e frases educativas. Estimula o aprendizado de números, letras e conceitos básicos de forma interativa. Tamanho ideal para mãos pequenas, facilitando a pegada e a exploração. Mais sobre o Produto:Desenvolve habilidades motoras finas. Estimula o aprendizado de números e letras. Promove a interação e a brincadeira educativa. Dicas de Uso:Utilize o controle remoto como uma ferramenta de aprendizado divertida. Explore as músicas, sons e frases para estimular a curiosidade e a criatividade do bebê. Ficha Técnica:Marca: Mattel; Nome do produto: Fisher-Price Controle Remoto Irmã do Cachorrinho; Idade Recomendada: A partir de 6 meses; Selo Inmetro: 00128-06A; Contém: 1 controle remoto.', 139.99, 139.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-82615-ml5j1g9xle6nfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F22797299539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
