INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593734695', 'Chuteira Society Penalty Matis Kids Y-3', 'Produzida para os pequenos campeões, a Chuteira Society Penalty Matis Kids Y-3 possui design moderno. O cabedal em Micropower oferece leveza, durabilidade e controle de bola, permitindo que você mantenha o domínio do jogo em todas as situações. A palmilha em EVA Plana de 3,5 mm proporciona amortecimento ideal a cada passo, reduzindo o impacto e a fadiga, para que você possa se concentrar totalmente no seu desempenho. Além disso, o solado emborrachado antiderrapante produzido com micro travas para os campos Society, auxiliam na flexão e movimentação dos pés durante as arrancadas e mudanças de direção. Não perca tempo, adquira já a sua!', 259.89, 144.88, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-81zuk-milt34kbfvggc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F23593734695', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
