INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41307805964', 'Alicate Universal 7'''' - 175mm (700009) - Onsite', 'O Alicate Universal 7'''' - 175mm (700009) - Onsite, é uma ferramenta necessária em todas as caixas de ferramentas, este modelo foi projetado para ser versátil e durável, com um tamanho de 7'''' (175mm), é a ferramenta perfeita para uma variedade de tarefas, desde cortar fios até apertar ou afrouxar parafusos. Fabricado com materiais de alta qualidade, este alicate é resistente ao desgaste, garantindo uma longa vida útil; com um design ergonômico, que te permite um manuseio seguro e confortável, tornando-o ideal para o uso prolongado. Características: - Modelo: Universal 7''''. - Tamanho: 175mm (7''''). - Com punho antideslizante. - Com cabo ergonômico. Código: 700009. Marca: Onsite. Tamanho: 175mm (7''''). Ean: 6942629231929.', 29.9, 29.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdw8-mby8f15w42k572', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F41307805964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
