INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599320735', 'Caneta Batom Rosa - Silky Lip Pen Magenta 4you 0,6ml', 'Quando a Gente Pensa em Maquiagem, a Boca É Uma Das Maiores Protagonistas do Look. e Se Você Curte Experimentar Produtos Diferentes para Inovar Na Hora de Se Maquiar, Vem Conhecer a Silky Lip Pen, Um Produto da Linha 4you No Formato de Caneta, Um Tipo de Aplicador Que Vai Facilitar Muito a Sua Vida. Silky Lip Pen Possui Uma Ponta Fina Que Delineia e Preenche Os Lábios com Muita Facilidade. o Produto Conta com Uma Textura Líquida Que Desliza Facilmente E, Por Ter Alta Pigmentação, Já Revela a Cor Logo de Cara! Sabe Aquela Boca com Cor Uniforme e com Formato Definido? É Esse o Efeito Que Você Vai Ter. com Este Aplicador, Não Tem Erro Na Hora DePassar o Batom Matte! A Cor Magenta, Aliás, É Um Rosa Marcante Que, Por Si Só, Já Dá Personalidade Ao Visual. o Acabamento Matte Deixa Um Resultado Sequinho Que Está Sempre em Alta. e Tudo Isso sem Comprometer a Hidratação Natural Dos Lábios. Já É Aquele Must-Have Que Você Vai Querer Levar Na Bolsa para Passar Sempre! E a Produção Vai Durar Bastante Tempo, Já Que Esse Batom em Caneta Possui Uma Fixação de Milhões. Lembrando Que o Produto É Vegano e Cruelty Free. Quanta Coisa Boa em Um Produto, Não Acha? Você Não Vai Querer Tirá-Lo Dos Seus Lábios. Quais São As Dicas para o Batom Não Sair de Jeito Nenhum? Com Algumas Dicas, Você Consegue Fazer o Seu Batom Durar Muito Tempo e Não Sair de Jeito Nenhum: - Hidrate Os Seus Lábios; - Faça o Contorno da Sua Boca; - Passe Uma Camada de Batom; - Tire o Excesso com Um Papel Toalha; - Aplique Outra Camada de Batom; - Aplique Uma Camada Fina de Pó Solto para Selar o Batom; - Passe Um Fixador de Maquiagem.', 49.9, 39.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mr25bq5ej4lg3e', 'https://shope.e