INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397332833', 'Soquete Impacto-M3 1/2 x 20mm (435,0013) - Noll', 'O soquete de impacto sextavado M3 1/2 X 20mm (435,0013) - Noll é uma ferramenta essencial para aplicações que requerem torque e resistência. Projetado para trabalhar com chaves de catraca ou máquinas de impacto, este soquete oferece desempenho confiável em diversas situações. • Projetado: Para apertar e afrouxar parafusos e porcas. • Formato: Sextavado. • Bitola: 20mm • Encaixe: 1/2". Referência: 435,0013 Marca: Noll O soquete de impacto sextavado M3 1/2 X 20mm (435,0013) - Noll é uma ferramenta essencial para aplicações que requerem torque e resistência. Projetado para trabalhar com chaves de catraca ou máquinas de impacto, este soquete oferece desempenho confiável em diversas situações.', 23.35, 23.35, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcd5-lrd84i9iksk636', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22397332833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099473827', 'Goiabinha Piraquê', 'O biscoito Piraquê de goiabinha é uma criação original e possui textura macia com delicioso recheio de goiaba, perfeito para o lanche da tarde ou café da manhã. Ideal para acompanhar um café, chá ou para matar a vontade de um docinho durante o dia.', 5.49, 5.49, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-8257w-mqnelbf8eolr45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F22099473827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24442857622', '[Novo] óleo de limpeza de colágeno de biodance, 200ml', 'Características: Contra colágeno-Enriquecido: Contém colágeno, que ajuda a melhorar a elasticidade e hidratação da pele. Fórmula leve: Ao contrário dos poros e emulsiona rapidamente após o contato com água, deixando um acabamento fresco e não oleoso: Ao contrário dos óleos pesados, não obstrui os poros e emulsiona rapidamente após o contato com a água, deixando um acabamento fresco e não oleoso. Limpeza profunda: Remove efetivamente a maquiagem e as impurezas, mantendo a pele limpa e refrescada. Modo de usar: 1. Em mãos secas. 2. Massagem suavemente: Aplique o óleo uniformemente sobre o rosto e massageie suavemente para dissolver a maquiagem e as impurezas. 3. Emulsione uma pequena quantidade de água nas mãos e massageie o óleo até que o óleo se transforme em uma textura leitosa. 4. Enxaguar completamente: Use água morna para enxaguar completamente o óleo e impurezas. Ingredientes completos Palmitato de Etilhexil, Etilhexanoato de Cetila, Diisoestearato de Poligliceril-10, Dicaprato de Poligliceril-6, Sesquiolato de Sorbitan, Laurato de Poligliceril-2, Água Purificada, Extrato de Pêra, Água de Flor de Rosa Damasco, Extrato de Eclipta Prostrata, Extrato de Raiz Orris, Extrato de Semente de Melão, Ivy Inglês Extrato de folha/caule, extrato de folha de Neem, caprililglicerina, óleo de semente de uva, óleo de semente de girassol, óleo de semente de Jojoba, etilhexilglicerina, óleo de semente de Moringa, butilenoglicol, 1,2-hexanodiol, extrato de colágeno (100 ppb), acetil hexapeptídeo-8, tocoferol, Oligopeptídeo-1, Tripeptídeo de Cobre-1, Pentapeptídeo de Palmitoil-4, Tripeptídeo-1, Hexapeptídeo-9, Tripeptídeo de Cobre-1, Pentapeptídeo de Palmitoil-4, Tripeptídeo de Palmitoil-5, Tripeptídeo-1, Hexapeptídeo-9, Tripeptídeo de Palmitoil-38, Pentapeptídeo-4, Hexapeptídeo-12.', 145.16, 145.16, NULL, 'Beauty > Makeup > Makeup Removers', 'https://cf.shopee.com.br/file/sg-11134207-7rd4j-m7iyyyezg25yac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24442857622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
