INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799095569', 'Par Lente Lanterna Traseira D20 A20 C20 1985 a 1996 Tricolor', '**Leia com ATENÇÃO todas as informações do anúncio e compre somente na certeza. Verifique o modelo, ano, ou qualquer dúvida nos contate no campo de perguntas antes de finalizar a compra. O custo por eventual devolução será por conta do comprador! ** Produto 1ª Linha (NÃO É ORIGINAL) -DESCRIÇÃO: Par Lente Lanterna Traseira (Tricolor) -COMPATÍVEL: Chevrolet - A20 / C20 / D20 1985 a 1996 -ITENS INCLUSOS: 01 - Lente da Lanterna Traseira - Lado Direito (Passageiro) 01 - Lente da Lanterna Traseira - Lado Esquerdo (Motorista) -ESPECIFICAÇÕES TÉCNICAS: Tricolor Altura: 31cm / Comprimento: 13,5cm Alta Durabilidade Material: Plástico Excelente Acabamento Não Acompanha Lâmpadas ou Soquetes -OBSERVAÇÕES: * Anúncio referente ao PAR! * Recomendamos que os produtos sejam instalados por profissionais especializados. * Não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. * Imagem meramente ilustrativa. * Atenção: Não Permitimos a utilização de nossas fotos e/ou vídeos a terceiros. * Não vendemos para PESSOA JURÍDICA fora do ESTADO DE SÃO PAULO. *Caro Cliente! Caso precise devolver o produto, independente do motivo, se atente ao prazo oferecido pela Plataforma. Não encerre por conta própria seu pedido de devolução até que o mesmo se resolva! Após o vencimento/encerramento, não poderá mais usufruir dessa cortesia e os custos serão por sua conta.', 79.39, 74.63, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mccg337jarc0ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F18799095569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19109262689', 'Top Feminino Mormaii Nadador Beach Sports Liso Original Novo', 'TOP FEMININO MORMAII PRODUTO ORIGINAL COM NOTA FISCAL Top Feminino Mormaii Nadador com proteção UV50+ costas nadador com alça fina, decorte redondo, boa sustentação, confortável e perfeito para atividades de alto impacto e movimento. Ideal para a prática de exercícios físicos ou compor um look descontraído no dia a dia ou para pratica de esportes ao ar livre como Beach Tennis, FuteVolei entre outros esportes. Feito em tecido leve de secagem rápida, ideal para a prática esportiva. CARACTERÍSTICAS DO PRODUTO Composição:82% Poliéster e 18% Elastano Proteção Solar 50+ MORMAII: A história da Mormaii começa nas belas praias da região sul do litoral brasileiro no início dos anos 70, fundada pelo então médico e surfista Morongo. Surge, assim, uma marca com raízes no surfe, mas com um objetivo maior: a busca pela qualidade de vida. Atualmente, a marca é reconhecida por mais de uma centena de produtos que atendem as categorias Surf, Mergulho, Skate, Fitness, Moda Praia, Bicicletas, além de produtos como óculos, relógios e chinelos, entre outros, tornando a Mormaii a maior e mais querida marca de esportes livres do Brasil.', 119.9, 119.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mavopx5b3mrdcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F19109262689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
