INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40414231899', 'Relógio Masculino Chroma Preto Couro com Caixa Prata Saint Germain Design Elegante Clássico', 'Relógio Masculino Clássico Couro Preto com Caixa Prata — Sofisticação Atemporal com Design Elegante Um modelo que une o charme do clássico com a modernidade do minimalismo. Ideal para homens que buscam um acessório discreto, elegante e versátil para acompanhar todos os momentos do dia a dia. Com visual limpo, mostrador preto com função calendário e acabamento sofisticado, ele se adapta perfeitamente do escritório ao jantar. Um relógio que transmite bom gosto e atenção aos detalhes sem exageros, mas com muita personalidade. Benefícios Caixa prateada com mostrador preto e marcadores metálicos Função calendário prática no mostrador Movimento de quartzo de alta precisão Bateria modelo 377 já instalada Resistente apenas a respingos (não indicado para mergulho) Detalhes Técnicos Diâmetro da caixa: 42 mm Espessura da caixa: 6 mm Comprimento da pulseira: 22–23 cm (corrigido, não 49 cm) Largura da pulseira: 22 mm Material da pulseira: Couro sintético preto Material da caixa: Metal prateado Material do vidro: Vidro mineral simples Movimento: Quartzo Resistência à água: Apenas respingos Tipo de fecho: Fivela tradicional Tipo de bateria: 377 Garanta já o seu Relógio Masculino Saint Germain Couro Preto Caixa Prata e adicione ao seu visual um acessório que combina elegância atemporal e praticidade em cada detalhe.', 209.9, 129.9, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdnoccvmnant6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411289902%2F40414231899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42054129349', 'ATTACK SHARK X11SE Mouse Para Jogos Sem Fio Ultraleve Tri-Mode-2.4G/USB-C Com/BT PixArt PAW3311 Sensor De 22KDPI', 'Rato esportivo de tubarão X11SE】59g ultraleve | Sensor PAW3311 | Conexão de três modos | Micro-movimentos de 20 milhões 【Design ultraleve de 59g | Batalha de longa duração sem fadiga】 Projetado para jogadores FPS/MOBA, "CS2" e "Desastre externo" não serão cansados por muito tempo Curvas ergonômicas, aderência/peg confortavelmente e mais de mão 【Sensor de jogo PAW3311 | Rastreamento preciso】 Ajustável 22000 DPI ajustável | Velocidade de rastreamento de 400 IPS de 400 IPS | Aceleração de 40G de aceleração Estrutura de salto zero/gatilho zero, pistola de comer frango é tão estável quanto uma rocha, o posicionamento MOBA está travado com precisão 【Conexão ultravelocidade de três modos | Comutação de um clique em um clique】 Tipo-C/2.4G sem fio/Bluetooth 5.0, adaptado ao PC/notebook/tablet/telefone celular Chip de controle principal nórdico BK52820 BK52820, atraso de sinal estável 0, comutação perfeita de escritório de jogos 【Micro movimentos Huano de 20 milhões | Dez anos de durabilidade】 Problema de clique duplo Eliminar o problema de clique duplo, a vida útil dos botões é 3 vezes a do mouse comum Feedback de gatilho de nível Esports, aumentando em 50% a velocidade de conexão dos pontos de conexão 【Driver de nuvem inteligente | Configurações sem instalação】 Não precisa baixar o driver! Configuração de um clique de DPI/devolução/botões macro por navegador Suporte a programação macro, dobre a eficiência de operação rápida de combinação/escritório de um clique', 251.03, 119.0, NULL, 'Computers & Accessories > Keyboards & Mice > Mice', 'https://cf.shopee.com.br/file/cn-11134207-820l4-mhk9pmi6ieitca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsh