INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43870759263', 'Parabarro Dianteiro City 2015 2016 á 2021 Direito', 'Parabarro Dianteiro City 2015 2016 2017 2018 2019 2020 2021 Direito - ANUNCIO REFERENTE A UNIDADE! (Lado Direito Passageiro) Descrição do Produto Com Parabarro o seu carro está protegido dos respingos de barro, lama e sujeira nas peças internas. Além de ser um item para cuidar da estética, também é uma medida de segurança. Especificações do Produto - Textura Lisa - Material em Plástico Compatível com: - City 2015 - City 2016 - City 2017 - City 2018 - City 2019 - City 2020 - City 2021 Especificação Técnica: • Peça Dianteira • Não Acompanha Presilhas O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: • 01 Parabarro Dianteiro Direito FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Detalhes técnicos e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 169.9, 146.12, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Mud Flaps', 'https://cf.shopee.com.br/file/br-11134275-81z1k-meq1t0b8vv9c0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F43870759263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8315744301', 'Ralo Inox 15cm com Fechamento Automático Lorenzetti', 'Tecnologia que libera o escoamento da água por meio do seu peso e fecha automaticamente Os ralos são a conexão direta com o esgoto, ou seja, podem ser a porta de entrada para a proliferação de pragas no lar. As Grelhas LorenProtect contam com sistema exclusivo, que funciona como uma gangorra que libera o escoamento da água por meio do seu peso e fecha automaticamente. O mecanismo inteligente das Grelhas LorenProtect impede a entrada na casa de insetos e aracnídeos, como escorpião, e a proliferação de larvas e pragas, principalmente, do Aedes Aegypti, minimizando o risco de dengue, chikungunya e zika vírus. Como o escoamento ocorre automaticamente, não existe risco de inundação da casa num eventual vazamento de água, como ocorre com grelhas de abertura e fechamento manual. Além disso, o sistema mantém o acesso restrito para o lado interno da casa, evitando o retorno de espuma de máquina de lavar. Produzidas em aço inox 304, as Grelhas LorenProtect apresentam mais durabilidade e resistência em comparação com outros modelos, pois não enferruja e nem oxida. Disponível nas versões redonda e quadrada, de 100mm e 150mm, tamanhos padrões do mercado, os produtos garantem facilidade para a substituição. Garantia: 5 anos na Rede de Assistência Técnica Autorizada Lorenzetti, como rege o Termo de Garantia que acompanha o produto. SAC 0800 016 0211 opção 3.', 117.9, 117.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-lzam1fkebiug90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F305108896%2F8315744301', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
