INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41979205270', 'Sutiã Top Nayane Com Bojo Sem Aro Decote V Laterais Largas Confortável', 'Sutiã Top Bojo Tri Sem Aros Conforto Ref. NRST110025 O sutiã top Nayane com bojo foi desenvolvido para oferecer sustentação, conforto e ajuste perfeito ao corpo. Sua modelagem combina a tecnologia de sutiã com o conforto de um top, garantindo mais praticidade para o uso no dia a dia. O modelo possui bojo que ajuda a modelar o busto sem a necessidade de aro, proporcionando mais conforto. Conta com decote em V que valoriza o colo, laterais largas que oferecem maior sustentação e alças forradas fixas com regulagem para melhor ajuste. Um sutiã feminino confortável, moderno e ideal para mulheres que buscam sustentação e bem estar durante todo o dia. Composição: 91% Poliamida, 09% Elastano. Benefícios do produto -Modelo com bojo que ajuda a modelar o busto -Sem aro para maior conforto -Decote em V que valoriza o colo -Laterais largas que oferecem mais sustentação -Alças forradas fixas com regulagem -Modelo confortável ideal para o dia a dia Tabela de tamanhos 42 busto 88 a 92 cm 44 busto 92 a 96 cm 46 busto 96 a 100 cm 48 busto 100 a 104 cm', 98.97, 61.99, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/br-11134207-820m2-mr1p4h55x5om5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800864347%2F41979205270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40020643310', 'Conector Cotovelo Joelho Engate Rápido 5/16 X 5/16 – Adaptador para Filtro, Purificador e Mangueira', 'Facilite sua instalação hidráulica com o conector cotovelo engate rápido 5/16 X 5/16, ideal para realizar conexões seguras e eficientes em sistemas de água. Seu formato em 90 graus permite melhor direcionamento da mangueira, sendo perfeito para locais com pouco espaço e evitando dobras que prejudicam o fluxo. O sistema de engate rápido proporciona uma instalação simples e firme, dispensando o uso de ferramentas. Basta encaixar as mangueiras para obter uma vedação eficiente, sem vazamentos e com excelente desempenho no uso contínuo. Diferenciais Engate rápido prático, sem necessidade de ferramentas Conexão 5/16 X 5/16 com encaixe firme e seguro Formato em cotovelo (90°) ideal para espaços reduzidos Vedação eficiente, evitando vazamentos Instalação rápida e prática Alta resistência e longa durabilidade Indicado para uso residencial e profissional Aplicações Filtros e purificadores de água Sistemas de osmose reversa Geladeiras com dispenser Bebedouros Sistemas hidráulicos e de refrigeração Jardins e irrigação Aquários Informações técnicas Modelo: Conector cotovelo 90° Conexões: Engate rápido 5/16 X 5/16 Material: Plástico resistente e atóxico Compatibilidade: Mangueiras padrão 5/16 Modo de uso Insira as mangueiras nos encaixes até o travamento completo Verifique se estão bem fixadas para garantir vedação Para remover, pressione o anel do engate e puxe a mangueira Solução ideal para quem busca praticidade, vedação confiável e eficiência na instalação de sistemas hidráulicos.', 16.9, 15.21, NULL, 'Home & Living > Tools & Home Improvement > Air Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820l5-mo8b15jepybm33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F506112052%2F40020643310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
