INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40322673371', 'Óleo labial essence Juicy Bomb Party 03 Manga', '✨ ÓLEO LABIAL JUICY BOMB PARTY Prepare-se para brilhar com o Óleo Labial Juicy Bomb Party da essence, perfeito para conquistar lábios suaves, hidratados e naturalmente radiantes. Sua fórmula nutritiva envolve os lábios com conforto enquanto entrega um acabamento ultrabrilhante e não pegajoso. Com um delicioso aroma frutado de pêssego, ele traz um toque divertido e refrescante para o dia a dia. Ideal para qualquer momento — seja para sair com amigos ou curtir um momento relaxante — realçando a beleza natural dos lábios com um brilho irresistível e toque sutil de cor. 💧 Fórmula Altamente Nutritiva Ajuda a manter os lábios macios e hidratados ao longo do dia. ✨ Brilho Ultrabrilhante Proporciona acabamento luminoso sem sensação pegajosa. 🍑 Fragrância Frutada de Pêssego Aroma suave e delicioso que torna o uso ainda mais agradável. 💋 Lábios Radiantes Naturalmente Realça a beleza dos lábios com brilho e hidratação. 🌟 Perfeito para o Dia a Dia Ideal para quem busca praticidade, conforto e um glow natural. 🌿 Sobre a Marca A essence é a marca nº 1 na Europa em unidades de cosméticos*, oferecendo qualidade com preço acessível. 100% livre de crueldade animal desde o início, com forte compromisso com produtos veganos. Acreditamos em uma beleza divertida, acessível e responsável. Para a essence, cada pessoa é única — o perfeito é ser você. *Marca de cosméticos em unidades.', 19.9, 19.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-824hw-mfcs5dlfqsy0fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F40322673371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18326265371', 'Máscara em gel para sobrancelhas Make Me BROW essence 5 Chocolaty Brows', '✨ MÁSCARA EM GEL PARA SOBRANCELHAS MAKE ME BROW Sobrancelhas definidas, preenchidas e naturalmente volumosas em poucos segundos. A máscara em gel Make Me Brow da essence colore, modela e preenche falhas indesejadas, proporcionando um acabamento uniforme e um look impecável. Sua fórmula com pequenas fibras auxilia no preenchimento, criando efeito de sobrancelhas mais cheias e bem definidas. Além disso, conta com ingredientes nutritivos como óleo de açaí e manteiga de manga, que ajudam no cuidado dos fios. Praticidade, definição e efeito natural em um único produto. 🌿 Preenche e Define Colore e modela as sobrancelhas com efeito natural. ✨ Com Fibras Preenchedoras Ajuda a preencher falhas e aumentar a aparência de volume. 💚 Com Óleo de Açaí e Manteiga de Manga Ingredientes nutritivos que auxiliam no cuidado dos fios. 🎯 Resultado Uniforme e Natural Sobrancelhas mais cheias e bem desenhadas. 🌿 Sobre a Marca A essence é a marca nº 1 na Europa em unidades de cosméticos*, oferecendo qualidade com preço acessível. 100% livre de crueldade animal desde o início, com forte compromisso com produtos veganos. Acreditamos em uma beleza divertida, acessível e responsável. Para a essence, cada pessoa é única — o perfeito é ser você. *Marca de cosméticos em unidades.', 32.9, 32.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln3omkex3l8jf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F18326265371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993673209', 'Tênis Redley Originals Colors Feminino Rosa', 'Composição cabedal (parte superior): Material têxtil Palmilha: Em EVA; moldada e removível Solado: Borracha antiderrapante Forro: Material têxtil respirável Cor predominante: Rosa Lingueta: Fina e flexível Indicado para: Casual Origem: Nacional Gênero: Feminino Ajuste: Cadarço Peso aproximado: 620g o par nº 37', 164.9, 164.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rbna-m5lv9wj1w8jyef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F22993673209', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
