INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897736138', 'Pneu Speedmax Aro 18 Controlmax Plus CP12 185/35R18 76H XL', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 453.98, 417.67, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Agriculture Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-lzkon9x0df16ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23897736138', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
