INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193265007', 'Pingente de Prata 925 Cruz com Cristo', 'Pingente de Prata 925 Cruz com Cristo Este elegante pingente de prata 925 é uma peça clássica e religiosa, destacando a figura de Cristo em uma cruz detalhada. Perfeito para expressar sua fé e estilo com sofisticação. Especificações: Tamanho: 2cm (20mm) x 1,4cm (14mm) Peso: 0,74g Material: Prata 925 Características Principais: Design religioso com Cristo na cruz Feito em prata 925 de alta qualidade Leve e confortável para uso diário Descrição Detalhada: O Pingente de Prata 925 Cruz com Cristo é uma peça de joalheria que reflete a devoção e a espiritualidade. A cruz em prata 925 simboliza a fé, enquanto a figura de Cristo adiciona um toque de reverência. Com acabamento impecável, este pingente pode ser combinado com diferentes tipos de correntes, trazendo um brilho sutil e uma mensagem poderosa ao visual. Cuidados com o Produto: Para manter o seu pingente sempre bonito, evite o contato com produtos químicos, como perfumes e cremes, e guarde-o em local seco e limpo após o uso. Garanta já o seu! Adicione o Pingente de Prata 925 Cruz com Cristo à sua coleção e leve consigo um símbolo de fé e estilo em qualquer ocasião.', 65.0, 46.8, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzutkw07j53pe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23193265007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
