INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196683152', 'Encordoamento Guitarra Giannini Híbrida Electric GEEGSTH9 Nickel .009', 'Encordoamento Guitarra Giannini Híbrida Electric GEEGSTH9 Nickel .009A série Electric traz toda a sonoridade dos encordoamentos Giannini para a sua guitarra e contrabaixo. O encordoamento para guitarra Giannini GEEGSTH9 é um encordoamento híbrido, composto de um núcleo de aço revestido por Níquel, produz um som brilhante e agressivo que atende grandes variedades de estilos musicais, sendo bem resistente a oxidação e corrosão. Acompanha uma corda Mi extra grátis! Especificações: Fabricação: BrasilAlma: AçoRevestimento: NíquelAcabamento: BolinhaComprimento de escala: 648 mm / 25 1/2″ Inch A: 0.009; 0.011; 0.016; 0.026; 0.036; 0.046*Imagens Ilustrativas* *Garantia: 3 Meses*', 54.75, 49.28, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkqsfqiyaumt17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F23196683152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
