INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51756915281', 'Lente Vidro Retrovisor Gol G3 Golf 2000 A 2006 Bora Com Base', '🚀 ENVIO IMEDIATO — PRODUTO EM ESTOQUE NO BRASIL! ⚡ Produto à pronta entrega no Brasil. Receba rápido, sem esperar semanas. ⚙️ Recupere a visão clara do retrovisor e volte a dirigir com mais segurança. Esta lente de espelho retrovisor é a reposição ideal quando o espelho está quebrado, riscado ou opaco, restaurando a visibilidade e a funcionalidade do retrovisor do veículo. 🚗 Compatível com: Volkswagen – Gol G3 2000 a 2005 Volkswagen – Golf 2000 a 2006 Volkswagen – Bora 2000 a 2011 ℹ️ Mais Informações: Aplicação: Retrovisor externo Material da lente: Vidro metalizado Material da base: Plástico ABS virgem Fixação através de encaixes Possui fita inteiriça antiestilhaçante Alta durabilidade Excelente acabamento Acompanha base já fixada na lente Produto novo, embalado e protegido 90 dias de garantia e suporte ao cliente 🏷️ Tags: #lentederetrovisor #espelhoretrovisor #lentegolg3 #lentegolf #lentebora #espelhoretrovisorgolg3 #espelhoretrovisorgolf #espelhoretrovisorbora #vidroretrovisor #vidroretrovisorgolg3 #vidroretrovisorgolf #vidroretrovisorbora #espelhoretrovisorvolkswagen #retrovisorgolg3 #retrovisorgolf #retrovisorbora #pecasgolg3 #pecasgolf #pecasbora #autopecasvolkswagen #reposicaoretrovisor #segurancaveicular #kyodaiacessorios', 49.48, 45.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-820mh-mljaa7bs4t1g8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F51756915281', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
