INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257123710', 'Conjunto Infantil Menino Esportivo Zíper Colorittá Verde', 'O Conjunto Colorittá é composto por blusão e calça em moletom ponto roma. O blusão possui punhos nas mangas e barra, além de gola alta com meio zíper frontal e bolsos funcionais, que trazem um toque esportivo e moderno ao visual. Já a calça jogger conta com elástico no cós e detalhes em nervuras. Ideal para passeios ao ar livre ou viagens, esse conjunto é a escolha certa para completar o guarda-roupa infantil com personalidade. Aposte!Detalhes da peça: • Conjunto composto por blusão e calça • Feito em moletom ponto roma • Possui mangas longas • Possui gola alta com abertura em zíper • Possui bolsos • Elástico no cós • Ideal para passeios ao ar livre ou viagens', 259.9, 155.94, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259q-mr1ts5errrpd6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58257123710', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
