INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699187066', 'Aminoácido BCAA 2044mg 2:1:1 - 90 Cápsulas - Integral Médica', 'COMPOSIÇÃO DO ANÚNCIO 1x AMINO BCAA 2044 MG - 90 CÁPSULAS - INTEGRALMEDICA DESCRIÇÃO DO PRODUTO "BCAA 2:1:1: BCAAs (aminoácidos de cadeia ramificada) são componentes fundamentais das estruturas musculares. Uma vez que não sintetizados naturalmente por nosso organismo, precisam ser ingeridos por meio da alimentação ou suplementação. BCAA 2:1:1 fornece energia, possui ação anti-catabólica durante os treinos e favorece a recuperação muscular e síntese proteica após o treino. Benefícios: -Aumenta a síntese de proteína -Reduz o catabolismo (quebra de proteína) -Recuperação e crescimento muscular -Resistência física -Fonte de energia -Ganho de força e massa muscular Ingredientes: Leucina, isoleucina, valina, piridoxina (vitamina B6), cápsula (gelatina e água), celulose microcristalina (antiaglutinante) e dióxido de silício (antiumectante). Sugestão de Uso: Consumir 04 cápsulas ao dia ou conforme orientação profissional.', 49.99, 49.99, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqj6ftk20jdz6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F18699187066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
