INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200555345', 'MARTELO DE BORRACHA PRETA, CABO DE MADEIRA 1PC // SPARTA', 'Martelo de Poliuretano Anti-Retorno Sparta 1113055 Ferramenta versátil e confiável, ideal para assentar cerâmicas, laminados, endireitar metais e montar móveis, proporcionando precisão e cuidado em cada tarefa. Principais Vantagens: Confiabilidade reforçada: Cabeça firmemente fixada ao cabo, garantindo segurança e resistência mesmo em trabalhos intensos. Alta resistência mecânica: Cabeça em borracha de qualidade com dureza de 80 Shore, que suporta desgaste e impactos sem perder a eficiência. Proteção do cabo: Cabo de madeira com acabamento transparente que preserva a madeira e aumenta sua durabilidade. Conforto no uso: Cabeça leve de 225 g aliada a um cabo ergonômico, permitindo uso prolongado sem fadiga. Versatilidade: Ideal para profissionais e entusiastas, atendendo a diversas necessidades em obras, montagens e reparos. O Martelo de Poliuretano Anti-Retorno Sparta 1113055 é a escolha perfeita para quem busca uma ferramenta durável, confortável e precisa, garantindo eficiência e qualidade em todos os projetos.', 16.72, 16.72, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fc-mgz1m1wbfh8p5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58200555345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892951123', 'Filtro Ar Gol G4 G5 1.0 2002/... Wega FAP2214', 'DESCRIÇÃO: A Wega é uma empresa especializada na fabricação de diversos produtos automotivos, incluindo filtros de ar, que tem como sua principal função filtrar as impurezas presentes no ar antes que ele seja admitido no sistema de combustão do motor. O filtro de ar ajuda a prolongar a vida útil do motor, reduzir o desgaste e manter um desempenho consistente com mais economia. O filtro de ar Wega é um componente essencial para manter a saúde e o desempenho do motor do seu veículo FILTRO DE AR: FAP2214 MARCA: WEGA APLICAÇÃO: GOL G3 G4 1.0 4 CIL 8V: 2002 --> GOL FLEX G4 G5 1.0 16V: 2004 -- 2008 FOX 1.0 4 CIL 8V: 2003 -- 2008 MEDIDAS: Peso Bruto Unitário - 0,23 Comprimento Cx Peça - 28.8 Largura Cx Peça - 19.6 Altura Cx Peça - 3.6 Tem alguma dúvida? Podemos ajudar! Confira as informações abaixo: • Todos os nossos produtos são novos, originais e possuem garantia. • Todos os produtos anunciados estão disponíveis em estoque e são enviados com extrema rapidez. • O frete pode ser simulado antes de efetuar a compra, basta clicar em “ver custos de envio”. • A NF é emitida automaticamente com os mesmos dados cadastrados em sua conta. PARA CNPJ FORA DO ESTADO DE SP O RECOLHIMENTO E PAGAMENTO DA ST É OBRIGATÓRIO POR PARTE DO CLIENTE ANTES DO ENVIO. Cobrança de ICMS conforme Protocolo ICMS 41 de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado consulte a Cláusula Segunda §1° do referido Protocolo. • Verifique o endereço de entrega cadastrado e atualize caso necessário. • Confirme se a peça é correta para o seu modelo de veículo. • Para peças automotivas, recomendamos a instalação por um profissional especializado. Caso possua outras dúvidas, entre em contato.VALOR REFERENTE: WGFAP2214', 28.0, 28.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rccq-ltwthojt87wx98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290560683%2F22892951123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
