INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17932728433', 'Gincana Bíblica | Silvio Nakano', 'Conhece o ditado: ´´Brincando a gente aprende``? É o que este livro proporcionará para famílias, igrejas, retiros, encontros, acampamentos, escola bíblica. Uma maneira fácil e divertida de estudar a Palavra de Deus.São mais de 2.000 questões bíblicas com várias opções de resposta para você acertar e conhecer a Bíblia! 14x21cm 188 Páginas', 35.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/3dc1c39beb9dbd1d6e783cf744a9b086', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F17932728433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23430339916', 'Encontrando-se com Jesus | Um Plano de Leitura Bíblica para Crianças | David Murray', 'APRESENTE O SALVADOR DO MUNDO ÀS CRIANÇAS Este plano de leitura anual da Bíblia para crianças de 6 a 12 anos as guiará pela vida de Cristo e lhes ensinará o que as Escrituras dizem acerca de Jesus. Mesmo que disponha de apenas cinco minutos por dia, a criança conhecerá a vida e os ensinamentos de Jesus, com sua oferta de vida abundante a todos aqueles que creem em seu nome. CADA ENCONTRO SEMANAL INCLUI: ●Leituras bíblicas diárias●Pedidos de oração●Versículo para memorização●Perguntas para discussão●Espaço para anotações e reflexões sobre o sermão. ---------- “Encontrando-se com Jesus é uma joia, pois oferece às crianças ensino acessível e orientações ternas que podem levar a uma vida de boas práticas, e aos pais e avós um meio claro, cotidiano de lançá-las às mãos do Salvador.” ― Rosaria Butterfield, ex-professora de Inglês na Syracuse University; autora de O Evangelho e as Chaves de Casa “Encontrando-se com Jesus é uma ferramenta singela e maravilhosa para ensinar às crianças uma forma pessoal de investir em sua própria vida de piedade.” ― Lindsey Carlson, autora de Growing in Godliness: A Teen Girl’s Guide to Maturing in Christ “Nesta inestimável ferramenta para devoção diária, David Murray guia os pequenos em descobertas magníficas, comunicando-lhes com sinceridade o seu desejo de que conheçam Jesus onde ele pode ser encontrado: na Palavra de Deus escrita e pregada, e nos sacramentos. Recomendo com a expectativa de que famílias e igrejas usufruam desta obra!” ― Simonetta Carr, autora de Biografias Cristãs para Jovens Leitores 18x23cm 208 Páginas', 62.9, 62.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-23030-6upaerzd8eov71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23430339916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997783601', 'Balcão De Cozinha Andréia Branco Com Tampo 100 Cm Preto Fosco - Ajl', 'Balcão De Cozinha Andréia Branco Com Tampo 100 Cm Preto Fosco - Ajl Balcão de Cozinha Andréia Branco com Tampo 100 cm Preto Fosco AJL Na hora de comprar o balcão para cozinha procuramos por qualidade, resistência, amplo espaço, tudo isso com preços acessíveis e sem deixar a modernidade de lado, apresentamos a você essa linda opção: Balcão de Cozinha 100 cm da linha Andréia desenvolvido com materiais de excelentes qualidades pela AJL pensando em deixar a sua cozinha com um toque especial, design na cor Branco e acompanha Tampo Preto. Confira e garanta o seu! Balcão de Pia Andréia 100 cm Branco - AJL Características Técnicas: - Desenvolvido 100% em MDP - Acabamento em pintura U.V na cor Branco - Possui 02 Portas - Dobradiças em Aço - Puxadores embutidos - 03 Gavetas - Corrediças metálicas - Pés em PVC - Lindo design Dimensões: Altura: 80 cm Largura: 97 cm Profundidade: 51 cm Tampo Para Balcão 100 cm Preto Fosco - AJL Características Técnicas: - Desenvolvido 100% em MDP - Pintura e acabamento em U.V na cor Preto Fosco - Produto resistente - Ótima combinação com as mais variadas cores de móveis de cozinha Dimensôes: Altura: 15 mm Largura: 100 cm Profundidade: 51 cm Obs: Não realizamos a montagem, porém acompanha manual de instruções.', 352.45, 352.45, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-lypbf71oo01402', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F20997783601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
