INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13311875951', 'Fone De Ouvido Motorola Moto JR 200 Kids, Isolamento de ruido - Rosa', 'O Motorola Moto JR 200 são fones de ouvido que não permitem mais de 85 decibéis de altura, ou seja, que atendem a uma limitação adequada para crianças entre 3 e 8 anos preservando a audição das crianças. A construção é flexível com o objetivo de garantir sua segurança, resistência, durabilidade e conforto. E oferece a possibilidade de ligar até 2 fones ao mesmo tempo num único dispositivo eletrônico tornando a brincadeira muito mais divertida. ESPECIFICAÇÕES TECNICAS: - Microfone para chamadas viva-voz - Isolamento passivo de ruido - Controle de play pausa - Cabo destacável 1,2 metros - Conforto com almofadas acústicas antialérgicas - Confortável Resistente a quedas - Limitação de som adequada para crianças entre 3 e 8 anos CONTEÚDO DA CAIXA: Fone de ouvido Over-Ear Cabo 3.5mm Guia do usuário. CORES: Temos disponível a pronta entrega na cor do Anuncio. GARANTIA: Garantia de 12 meses para DEFEITOS DE FABRICAÇÃO. SOBRE O ENVIO: Todos os produtos anunciados são para pronta entrega, comprando hoje será enviado no próximo dia útil.', 224.6, 95.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lk172d65j8yu6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F527266444%2F13311875951', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694895364', 'Banco Selim Gel Plus 2 Molas GTA Largo Com Fita Refletiva Segurança Bicicleta Bike Mtb', 'Selim GTA Mega Soft Comfort Tech Conforto real para qualquer pedal Se você sofre com banco duro, desconforto ou dor após poucos minutos de uso, o Selim GTA Mega Soft Comfort foi desenvolvido para mudar isso. Projetado para oferecer máximo conforto em pedaladas longas e curtas, ele combina gel, molas e elastômero para reduzir impacto, vibração e trepidação. Diferenciais do produto • Gel Mega Soft para melhor absorção de impacto • Sistema com 2 molas para amortecimento eficiente • Elastômero que reduz vibrações • Modelo vazado para melhor ventilação e conforto anatômico • Refletor traseiro para mais segurança • Estrutura reforçada em aço • Acompanha carrinho para instalação Especificações técnicas Modelo: GTA Mega Soft Comfort Tech Dimensões: 260mm x 200mm Peso aproximado: 550g Composição: Nylon, Vinil e Ligas Metálicas Material da estrutura: Aço com revestimento em PU Modalidade: MTB e uso urbano Ideal para • Uso urbano diário • Pedaladas recreativas • Trilhas leves • Ciclistas que buscam mais conforto e estabilidade Mais conforto, mais segurança e mais durabilidade para sua bicicleta.', 59.89, 36.98, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-820lm-mm6atfr5isxs30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680833439%2F23694895364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898275152', 'Sala de Jantar Lola Mesa Tampo de Madeira 2 Cadeiras Madesa', 'Sala de Jantar Lola Mesa Tampo de Madeira 2 Cadeiras MadesaO Conjunto de Jantar Lola da Madesa é a opção perfeita para ambientes compactos que precisam de total aproveitamento do espaço. Características do Produto: - A mesa retangular com pés estruturais e tampo de madeira é firme e robusta. - As cadeiras possuem ótimo tamanho e são fabricadas em MDF, com encosto em pintura na cor Crema - Assento estofado em tecido Pérola, um material com toque suave e macio. - O acabamento é no padrão amadeirado Rustic. - Pintura em Poliéster de alta resistência com sete camadas de proteção, que oferece maior qualidade e durabilidade ao móvel. - O processo de pintura é ecológico, isento de vapores que prejudicam a atmosfera. - O conjunto é composto pela mesa e duas cadeiras. Especificações Técnicas: - Marca: Madesa - Itens Inclusos: 1 mesa com tampo retangular de madeira; 2 cadeiras com encosto em madeira pintada e assento estofado - Dimensões da Mesa (LxAxP): 104 cm x 76 cm x 78 cm - Dimensões da Embalagem (LxAxP): 40 cm X 98 cm X 49 cm - Acabamento: Pintura Poliéster - Cor: Amadeirado Rustic - Material do Tampo: Madeira - Tecido: Pérola - Dimensões da Embalagem (LxAxP): 77,5 cm X 23,5 cm X 111 cm - Peso Bruto: 27,8 kg Garantia: 3 meses', 499.99, 499.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rdxg-mcj7cnry2p4je8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F19898275152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18461661803', 'Telefone com Fio Intelbras TC 50 Preto', 'A solução perfeita em qualquer ambiente de trabalho. Assim é o TC 50 Premium Intelbras, além de todas as funções básicas, possui a exclusiva função modo PABX, que melhora o conforto do áudio do seu telefone quando conectado às centrais.', 92.9, 78.9, NULL, 'Home Appliances > Small Household Appliances > Telephones', 'https://cf.shopee.com.br/file/sg-11134201-8259o-mqrihdz06ccv33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859766415%2F18461661803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
