INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210088006', 'Pastilha Freio Traseiro Sinter Potenza Bmw R1250 Gs Rt 2019+', 'UM PAR DE PASTILHAS DE FREIO SINTERIZADAS TRASEIRAS POTENZA PTZ209GP À PRONTA ENTREGA! POSTAGEM IMEDIATA. Aplicações - Kit completo para o disco Traseiro: BMW: • R1250 GS ADVENTURE: 2019 à 2023. • R1250 GS: 2019 à 2023 • R1250 GS EXCLUSIVE: 2019 à 2023 • R1250 GS RALLYE: 2019 à 2023 • R1250 RT: 2019 à 2023 Sobre as pastilhas SINTERIZADAS : Sobre as pastilhas : • Utilizadas pelos mais renomados pilotos de moto velocidade. • Trabalham mais frias, ventilado exclusivo. • Garante precisão e rigoroso controle em frenagens bruscas. • Maior força de frenagem em situações onde você mais precisar. • Menor esforço na alavanca / pedal. • Maior durabilidade, recomendada para motos alta performance. • O maior coeficiente de fricção para a máxima força de frenagem • Fabricadas com liga de cobre sinterizado para uma maior direção e frenagem perfeita em quaisquer condições seco, molhado, frio ou calor. • O Composto SINTERIZADO Mantém as pastilhas mais frias e previne o seu engripamento e superaquecimento.', 319.9, 287.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-820lc-mnuhw84aez9gb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F58210088006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
