INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499297062', 'Adesivo Epóxi 16g Durepoxi Líquido - Loctite', 'É um epóxi bicomponente indicado para reparos em diferentes materiais, entre eles o vidro que necessita de tecnologias inovadoras para que não sejam feitos grumos durante a aplicação e que proporcionem secagem transparente.Cola á base de resina epóxi líquida com total transparência e secagem rápida.Super resistente é indicada para uma infinidade de materiais, podendo ser aplicada em superfícies porosas, lisas ou irregulares.Especificações:Cola epóxi transparente de secagem rápida;Adesivo líquido ideal para pequenas colagens e reparos;Garante fino acabamento com total transparência;Aderência super forte;Seca em apenas 10 minutos;Secagem e endurecimento à temperatura ambiente;Resiste à temperatura de até 70ºC;Após a secagem, torna-se uma película rígida incolor;Acompanha suporte plástico para mistuar os dois componentes.', 40.78, 31.9, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/sg-11134201-8259y-mqxoox0qoqv528', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1270088146%2F21499297062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
