INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21678287131', 'Vention Cabo Extensor USB 3.0 5Gbps Super Alta Velocidade De Sincronização De Dados Extensor Macho Para Fêmea PC Laptop', 'Descrição do produto em inglês após português Nome da extensor do USB 3.0 Nome: USB 3.0 Cabo de extensor Interface feminina: USB 3.0 Um Masculino/USB 3.0 A Feminino Técnicas de Interface de Interface de níquel: banhado a níquel Velocidade de transmissão de transmissão de 5 Gbps Condutor de cobre estanhado: Condutor de cobre estanhado Casca de casca de aço inoxidável:PVC Cor:Preto Blindagem de alumínio: folha de alumínio + trançado de Metal + GND Jaqueta: Jaqueta PVC AWG: 22+28AWG Embalagem: Bolsa PE Este cabo permite que você estenda as conexões USB entre seus dispositivos USB, proporcionando-lhe a liberdade de afastar sua área de trabalho enquanto estende as conexões USB entre seus dispositivos USB e USB, dando-lhe a liberdade de se afastar da área de trabalho enquanto usa seus dispositivos USB Você pode conectar dispositivos USB, teclados, dispositivos de armazenamento, como impressoras, teclados, dispositivos de armazenamento, telas USB Link de exibição, mouses e dispositivos USB mais populares remotamente com este cabo Blindagem premium e chipset inicial: o cabo apresenta blindagem premium e um chipset de aumento embutido que fornece proteção contra interferências de sinais EMI/RFI, permitindo assim alta performance. Compatibilidade Universal Compatibilidade Não é necessário drivers em nenhum OS, incluindo Windows, Mac OS, Linux, Chrome OS, não é necessário drivers em qualquer OS, incluindo Windows, Mac OS, Linux, Chrome OS, etc. Interface banhada a níquel: Resistente ao desgaste, anti-oxidação, durável em trocas de níquel. Material do PVC Premium Premium: Flexível e de alta tenacidade, vida útil mais longa. Design de cauda longa de mudança de cabos: Recuse-se a trocar os cabos com frequência ************************************************** Name：USB 3.0 Extension Cable Interface：USB 3.0 A Male/USB 3.0 A Female Interface Technics：Nickel-plated Transmission Speed：5Gbps Conductor：Tinned-copper Shell：PVC Color：Black Shielding：Aluminum Foil+Metal Braided+GND Jacket：PVC AWG：22+28AWG OD：5.4mm Packing：PE Bag This cable lets you extend USB connections between your computer and USB devices thereby giving you the liberty to move away from your desktop while using your USB devices You can connect USB devices such as printers, keyboards, storage devices, Display Link USB displays, mice and most popular USB devices remotely with this cable Premium Shielding & Built in Boost Chipset: The Cable features premium shielding and a built-in boost chipset that provides protection against interference from EMI/RFI signals thus enabling high performance. Universal Compatibility No drivers required on any OS, including Windows, Mac OS, Linux, Chrome OS, etc. Nickel-plated Interface：Wear-resisitant，anti-oxidation，durable in Swapping. Premium PVC Material：Flexible and high tenacity，longer service life. Long Tail Design：Refuse to change cables frequently', 37.13, 24.85, NULL, 'Computers & Accessories > Network Components > Network Cables & Connectors', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-ma28b5e88ej686', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F236428860%2F21678287131', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11126701655', 'Puzzle Quebra Cabeça 500 Peças Selfie Pets 03742 - Grow', 'Que coisa mais fofa! Quem não fica encantado quando vê cãezinhos brincando?! Conosco não existem brigas por causa de raça. Só amizade e diversão. A não ser que o assunto seja um belo osso! Mania nas redes sociais, nós fazemos por causa da nossa simpatia e fofura. Se você também é fã de "dogs", junte-se a nós nesta selfie! Au-au! A Grow é pioneira e referência em quebra-cabeças no Brasil, desde 1977. Os melhores materiais são cuidadosamente selecionados sempre buscando qualidade para garantir um encaixe preciso e uma ótima experiência de montagem. A montagem de um quebra-cabeça, por passatempo ou por hobby, traz momentos de alegria a cada peça montada. Aos poucos, um pedaço do mundo vai se formando e, em pouco tempo, uma paisagem maravilhosa está completa! E a sensação de ter feito uma viagem ou cumprido um desafio gera uma satisfação inigualável.', 51.59, 45.49, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/5abcadead3dc2470ffc10189d25dfd51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F11126701655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
