INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20327992792', 'Kit Elseve Cachos dos Sonhos - Shampoo 400 ml + Condicionador 400 ml + Creme para Pentear 250 ml', 'Este kit contém: 1 Shampoo 400 ml Cachos Longo dos Sonhos 1 Condicionador 400 ml Cachos Longo dos Sonhos 1 Creme para Pentear 250 ml Cachos Longo dos Sonhos Com Ácido Hialurônico que preenche a fibra capilar com hidratação profunda e Óleo de Rícino que nutre profundamente e sela os fios até as pontas fortalecendo e definindo os cachos. - O Shampoo Nutri Preenchedor de Elseve, além de limpar as impurezas, preenche o cabelo com nutrição profunda até as pontas, para cachos mais longos, fortes e definidos desde o primeiro uso. - O Condicionador Selador de Elseve desembaraça instantaneamente os fios e preenche o cabelo com nutrição profunda até as pontas, para cachos mais longos, fortes e definidos desde o primeiro uso. - O Creme Para Pentear Nutritivo de L’Oréal Paris Elseve Cachos dos Sonhos preenche os fios com nutrição profunda até as pontas. Seu aliado para tratar e selar os cachos até as pontas para salvar os últimos 3 cm dos seus cachos. ²Com proteção térmica de até 230°C. Testes instrumentais: uso conjunto do shampoo + condicionador + creme para pentear.', 156.13, 156.13, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzp75go5a6g50c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689225278%2F20327992792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
