INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42727125451', 'Magnésio e Inositol - Abacaxi com Hortelã 210g - Body Action', 'INFORMAÇÕES DE DESTAQUE Fórmula Avançada: Combinação de magnésio e inositol em uma dosagem balanceada. Quantidade: 210g por embalagem, com excelente rendimento. Fácil de Diluir: Solúvel em água, sucos ou outras bebidas de sua preferência. DESCRIÇÃO O Magnésio & Inositol é um suplemento desenvolvido para promover a manutenção do sono e o bem-estar geral. O Magnésio & Inositol, são a combinação de 2 ingredientes que proporcionam maior bem estar e melhoram a qualidade do sono. BENEFÍCIOS Equilíbrio e Bem-Estar: O magnésio é essencial para diversas funções do corpo, enquanto o inositol contribui para o suporte ao bem-estar geral. Praticidade: Pode ser facilmente incorporado na sua rotina diária, seja em casa, no trabalho ou na academia. Fácil Absorção: Fórmula projetada para rápida assimilação pelo organismo. SUGESTÃO DE USO Misturar 7 g (1 scoop) em 150 ml de água. Consumir 1 (uma) porção 1 (uma) vez ao dia, preferencialmente 30 minutos antes de dormir. Informações Adicionais: Não contém glúten. Alérgicos: Pode conter derivados de leite e soja.', 150.0, 115.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-822wp-mi21m6xlm7epad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308390046%2F42727125451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
