INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19775025657', 'Kit 2 Porta Sabonete Liquido Luxo para Lavabo', '🧴✨ Kit com 2 Porta Sabonete Líquido 500ml – Elegância e Funcionalidade para Banheiro e Lavabo ✨ Transforme o visual do seu banheiro ou lavabo com o Kit com 2 Porta Sabonete Líquido 500ml, que une design sofisticado, praticidade e versatilidade. Com acabamento refinado e linhas modernas, ele segue a tendência do “menos é mais”, trazendo um toque de elegância e organização ao ambiente. Além de valorizar a decoração, o porta sabonete é extremamente funcional e pode ser utilizado de diversas formas: ideal para sabonete líquido, álcool em gel, detergente líquido ou outros produtos, sem limitar o uso. Fabricado em polipropileno de alta qualidade, é resistente, durável e fácil de limpar, perfeito para o uso diário. ✅ Destaques do Produto • Kit com 2 unidades • Capacidade de 500 ml cada – ideal para uso frequente • Design moderno e sofisticado – combina com qualquer decoração • Versátil – pode ser usado com sabonete líquido, álcool em gel ou outros líquidos • Material resistente e leve – fácil de limpar e manter • Acabamento elegante – valoriza o ambiente 📐 Especificações Técnicas • Produto: Porta Sabonete Líquido • Capacidade: 500 ml (cada unidade) • Dimensões: 8,5 x 17 cm (Comp. x Alt.) • Material: Polipropileno • Cores disponíveis: – Preto com Dourado – Preto com Prateado – Branco com Dourado – Branco com Prateado ✨ Mais organização, estilo e praticidade no seu dia a dia! Garanta agora o Kit com 2 Porta Sabonete Líquido 500ml e leve sofisticação para seu banheiro ou lavabo.', 65.84, 65.84, NULL, 'Home & Living > Bathrooms > Soap Dispensers, Holders & Boxes', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2gle85q5mqaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F19775