INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098211456', 'Kit Cueiro Karinho Flanelado Estampado 3 Peças', 'Kit Cueiro Karinho Flanelado Estampado - 3 Peças O Kit Cueiro Karinho é uma escolha aconchegante e prática para os bebês. Composto por 3 peças, cada cueiro é confeccionado em 100% algodão flanelado, proporcionando maciez e conforto para a pele sensível do bebê. Além da suavidade do tecido, o kit apresenta estampas encantadoras, adicionando um toque de charme ao enxoval do bebê. Os cueiros são versáteis, podendo ser utilizados para cobrir o bebê durante o sono, como manta ou para envolvê-lo com carinho. Informações Adicionais:Tamanho: Único Referência: 4121-423 Medidas aproximadas: 80cm x 50cm Marca: Karinho', 26.7, 26.7, NULL, 'Mom & Baby > Nursery > Mattresses & Bedding', 'https://cf.shopee.com.br/file/sg-11134201-7rccu-m6ee3t1hjv8y0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23098211456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693091257', 'Aparelho Jantar e Chá 20 Pçs Biona Donna Cena Inglesa', 'A coleção Donna Cena Inglesa faz uma viagem ao passado. Paisagens históricas retratadas em tons de azul compõem uma louça tradicional e clássica, perfeita para todas as ocasiões! Conteúdo da embalagem: 4 Pratos Rasos 24 cm, 4 Pratos Fundos 21,5 cm, 4 Pratos Sobremesa 18 cm, 4 Xícaras de chá 200 ml com Pires 14 cm - Garantia: 3 Meses para Defeitos de fabricação - Marca: Biona - Tipo da embalagem: Papelão pardo - Material: Cerâmica - Cor: Azul - Decoração: Estampado - Formato: Redondo - Tipo do jogo: Jantar e almoço - Linha: Donna - Modelo: Cena inglesa - Quantidade de peças: 20 - É kit de fábrica: Sim - É apto para lava-louças: Sim - É Apto para microondas: Sim ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 333.22, 285.98, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-lwix6t31qvpn4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F23693091257', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993588195', 'Kit Fraldas Papi Soft Estampado Com Bainha - 05 Peças', 'Kit Fraldas Papi Soft Estampado Com Bainha - 05 Peças Fralda SOFT Papi Baby é feita com nosso tecido SOFT PREMIUM ainda mais absorvente e macio. Seu tamanho de 78cm x 78cm proporciona inúmeras utilidades, como fraldinha para cochilar, fraldinha de ombro, fraldinha para proteger no bebê conforto ou carrinho, para forrar qualquer superfície quando necessário, entre outros. Vem com 5 unidades no pacote, sendo 2 estampadas e 3 tintas. As estampas trazem um toque especial e encantador, tornando o produto ideal tanto para o uso diário quanto para momentos especiais. Versáteis, as fraldas podem ser utilizadas como apoio, pano de boca, cobertor leve ou durante a amamentação. Duráveis e fáceis de lavar, este kit combina qualidade, estilo e praticidade para atender às necessidades do dia a dia. Um item essencial para o enxoval! Informações Adicionais: Tamanho: 78X78 Composição: Algodão Marca: Papi Dica: Item essencial no enxoval!', 108.6, 108.6, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rffy-m3qv8564tz1e45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22993588195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494171491', 'Fralda Bebê Incomfral Luxo Pinte e Borde 05 Peças', 'Fralda Bebê Incomfral Luxo Pinte e Borde 05 PeçasA Fralda Bebê Incomfral Luxo Pinte e Borde é um item essencial no enxoval do bebê, oferecendo conforto, maciez e praticidade. Confeccionada em tecido 100% algodão, é delicada ao toque e ideal para a pele sensível dos pequenos. Seu tecido duplo garante alta absorção, proporcionando mais segurança e proteção. Além disso, possui espaço especial para bordado, permitindo personalização com nomes e desenhos.Principais Características:&bull; Kit com 05 peças, ideal para o dia a dia do bebê&bull; Tamanho ,versátil para diversas utilidades&bull; Tecido 100% algodão, garantindo maciez e respirabilidade&bull; Tecido duplo, proporcionando maior durabilidade e resistência&bull; Alta absorção, mantendo o bebê sempre seco e protegido&bull; Toque extra macio, delicado para a pele do bebê&bull; Espaço para bordado, perfeito para personalização com nomes e desenhos&bull; Fácil de lavar e secagem rápida, ideal para uso contínuoInformações Adicionais:Medidas: 70x70 Cores: Branco Referência:32029011 Marca: Incomfral', 39.9, 39.9, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7ra0t-mbfomlrf94bga4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23494171491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53964006062', 'Colchão Para Berço 130x70Cm Americano Espuma D18 Hipoalergênico Certificado Confortável Para Bebês', '👶✨ Colchão para Berço Espuma D18 130x70x7cm – Mais Qualidade, Conforto e Segurança para o Sono do Seu Bebê! Ofereça ao seu bebê noites de sono mais tranquilas com um colchão desenvolvido para unir conforto, segurança e durabilidade. Produzido com espuma D18, ele proporciona o suporte ideal para o descanso, contribuindo para um ambiente mais confortável e acolhedor. 📐 Medidas • Comprimento: 130 cm • Largura: 70 cm • Altura: 7 cm 🌟 Diferenciais do Produto 🛏️ Espuma D18 de excelente qualidade 📏 Medida padrão para berços 130 x 70 cm 📜 Certificado pelo INMETRO 🦠 Proteção Antiácaro 🍃 Tratamento Antifungo 🤍 Material Hipoalergênico 🧵 Revestimento em tecido poliéster resistente 💪 Perfil reforçado nas bordas para maior durabilidade 🧼 Fácil limpeza e conservação 👶 Desenvolvido especialmente para o conforto do bebê 💙 Benefícios ✔️ Proporciona um sono mais confortável. ✔️ Excelente sustentação para o bebê. ✔️ Produto resistente para o uso diário. ✔️ Acabamento reforçado que aumenta a vida útil. ✔️ Ajuda a manter um ambiente mais limpo e saudável. ✔️ Encaixe perfeito para berços compatíveis. 📦 Conteúdo da Embalagem 📦 01 Colchão para Berço Espuma D18 ⚠️ Informações Importantes 🔹 Compatível com berços na medida 130 x 70 cm. 🔹 Produto certificado pelo INMETRO, atendendo aos padrões de qualidade e segurança. 🔹 A estampa do tecido pode variar conforme o lote de fabricação, mantendo as mesmas características técnicas. 🔹 Antes de finalizar a compra, confirme as medidas do seu berço para garantir o encaixe perfeito. 💛 Invista em um colchão que oferece conforto, proteção e qualidade para acompanhar cada fase do crescimento do seu bebê. Segurança, bem-estar e tranquilidade para toda a família! 👶🛏️', 299.0, 95.68, NULL, 'Mom & Baby > Nursery > Cribs & Cradles & Beds', 'https://cf.shopee.com.br/file/br-11134207-820md-mqnpwqn6qi2p71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467752495%2F53964006062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499183664', 'Kit Relação Honda Xre300 Corrente com Retentor Oring aço 1045', 'KIT TRANSMISSÃO XRE 300 RELAÇÃO HARDT COM RETENTOR ORING *** ------------------------ *** APLICAÇÃO *** Moto: Honda XRE 300 Anos: 2009 2010 2011 2012 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022 ------------------------ *** CONTEUDO DA EMBALAGEM *** 1 COROA: 39 DENTES 1 Pinhão: 13 Dentes 1 Corrente: 520x104 ------------------------ Os KITS de Transmissão Hardt são compostos de corrente com retentor Oring, pinhão e coroa. Cada peça é enviada em embalagens separadas para garantir melhor qualidade. ------------------------ *** CORRENTE *** - Menos ruido e reducao de paradas para regulagem de corrente, - Corrente com retentor Oring, um anel que protege os componentes da corrente evitando a entrada de residuos e agua na lubrificação dos pinos e buchas aumentando a vida útil do produto. ------------------------ *** COROA *** - Tratamento térmico por indução, assegura maior durabilidade das pecas; - Dentes com camada endurecida por tempera, para garantir menor desgaste; - Fabricada em Aço 1045, certificado de acordo com as normas internacionais. ------------------------ *** PINHÃO *** - Fabricada em Aço 1045 de alta durabilidade, desenvolvido para melhor performance; - Certificado de acordo com as normas internacionais; - Tratamento térmico - Desde já agradecemos a Preferencia . - Shopping da Motobike', 339.9, 288.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpse33phr7l30b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F531303273%2F18499183664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499315758', 'Capacete Texx Kratos Escamoteável certificado IMETRO e Óculos Interno Forro Removível Modelo 2026', 'DESCRIÇÃO DO PRODUTO Capacete escamoteável 90º com óculos solar interno; com certificação IMETRO CONSTRUÇÃO • Casco produzido em ABS; • Viseira externa produzida em policarbonato de 2,2 mm com tratamento antirrisco e antiembaçamento; • Viseira interna produzida em policarbonato de 2 mm com proteção UVA/UVB; TECNOLOGIA • Sistema de circulação de ar AIRTEXX, entradas de ar frontais e superiores, além de 4 saídas de ar para melhor circulação durante o uso; • Dutos de ar que dão acesso diretamente na viseira, quando aberta a entrada de ar frontal; • Forro interno com acabamento MFI , sendo removível produzido em Microfibra Inteligente TEXX e é capaz de evaporar suor e umidade rapidamente além de possuir tratamento anti-bactéria e anti-alérgico, proporcionando melhor qualidade no uso; • Botão deslizante para acionamento do óculos solar interno, sistema DOUBLE VISION; • Sistema EVO TEXX, botão com trava de queixeira; • Sistema troca rápido viseira; CONFORTO • Desenho do forro anatômico e acabamento em mesh; • Bochecheiras removíveis proporcionando melhor conforto; DESIGN • Bavete removível com acabamento em couro e tecido carbonado; • Contém narigueira intermediária removível; • Fixador de viseira garantindo um melhor isolamento acústico; • Casco aerodinâmico, com design moderno; • Espaço interno para inserção do intercomunicador com passagem para área externa do casco; AJUSTES • Cinta jugular em engate micrometric; CERTIFICAÇÃO • Certificado pelo Inmetro e 22.06 ECE (normativa europeia)', 779.0, 779.0, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-820mf-mni0pvqv9dkyc7', 'https://sh