INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27944271103', 'Sandália Feminina Salto Taça Médio Bico Folha Strass Brilhante Luxo Elegante Fechado Confortável', 'Sandália Feminina Stessy Brilhante Com Bico Folha Com design exclusivo e acabamento de luxo, essa sandália Stessy é a escolha ideal para quem ama moda com personalidade. Sandália elegante e moderna com bico folha, que afina e alonga visualmente os pés. Possui tiras finas delicadas cheias de strass com aparência de joia — um detalhe sofisticado que valoriza qualquer look. O salto taça de 6 cm tem brilho elegante, acabamento durável e não descasca com facilidade, mesmo com o uso contínuo. Modelo leve, confortável e versátil – ideal para festas, eventos e looks do dia a dia. Destaques do Produto: Bico folha – visual moderno e Confortável Salto taça 6 cm – estável e durável Tiras delicadas com strass – acabamento de luxo Palmilha macia – conforto garantido Fechamento no tornozelo com fivela ajustável Informações Adicionais: Foto real do produto Pronta entrega – envio em até 24h Forma normal – peça seu número habitual Tabela de Tamanhos: 34 - 22,5cm 35 - 23,5cm 36 - 24,0cm 37 - 24,5cm 38 - 25,5cm 39 - 26,0cm Com mais de 16 anos no mercado, a Stessy desenvolve calçados femininos com design exclusivo, qualidade própria e conforto real. Produzimos nossos próprios saltos e lançamos coleções que acompanham as maiores tendências da moda mundial – com o melhor custo-benefício.', 199.9, 109.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-8262v-ml59wdmtdudp10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410637624%2F27944271103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
