INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899146861', 'CINTA DE LIXA, GRAO 80, 533X75MM, 3PCS // MTX', 'Cinta de Lixa MTX P80 7428355 – Eficiência e Versatilidade para Processamento Intermediário A Cinta de Lixa MTX P80 7428355 é projetada para máquinas de lixar de fita de 75 x 533 mm, oferecendo excelente desempenho no processamento intermediário de superfícies em madeira, metal e plástico. Ideal para profissionais e entusiastas do faça você mesmo, essa cinta garante a remoção eficiente de verniz, tinta, ferrugem e rebarbas, além de preparar superfícies para acabamentos finais com qualidade superior. Vantagens Alta Velocidade de Processamento Grãos de óxido de alumínio com dureza e pontas afiadas garantem remoção rápida e eficaz do material, otimizando a produtividade. Versatilidade Compatível com diversos materiais, como madeira, metal e plástico, tornando-a indispensável em oficinas multifuncionais. Ideal para Processamento Intermediário Granulação P80 perfeita para suavizar superfícies e preparar materiais para etapas de acabamento mais finas. Durabilidade e Resistência Base de tecido combinado que assegura resistência ao desgaste, proporcionando longa vida útil e excelente custo-benefício. Adesão Superior do Abrasivo Cola à base de resina formaldeído fixa firmemente o abrasivo à base de tecido, ideal para madeira fresca (úmida), garantindo lixamento uniforme e consistente. A Cinta de Lixa MTX P80 7428355 é a escolha certa para quem deseja aliar eficiência, versatilidade e durabilidade no preparo de superfícies, assegurando acabamentos de alta qualidade em diversas aplicações.', 13.9, 13.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821d1-mh254fk481ze5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22899146