INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206344746', 'Aparador Trama com 2 gavetas 110cm de largura Artely', 'Aparador Artely Trama com 2 gavetas 110cm de largura Elegância e funcionalidade em um só produto Decore seu ambiente com o Aparador Artely Trama, a fusão perfeita entre elegância e funcionalidade. Com detalhes em impressão palha, ele oferece um acabamento refinado no estilo boho chic, adicionando sofisticação e destaque ao seu espaço. Organização eficiente O Aparador Trama conta com duas gavetas, ideais para manter tudo organizado, desde documentos até itens decorativos, garantindo que sua sala ou hall de entrada estejam sempre arrumados. Pés estáveis e modernos Seus pés em MDF sólidos garantem estabilidade e um visual moderno, harmonizando perfeitamente com diferentes estilos de decoração. Versatilidade de uso Com traseira revestida, o Aparador Trama pode ser utilizado em qualquer espaço, inclusive como divisória de ambientes ou atrás do sofá, proporcionando ainda mais versatilidade. Características Gerais: Pintura 3D no acabamento palha; Corrediças telescópicas; Frentes de gavetas almofadas; Pés de MDF 25mm. Material: MDF 25 mm, MDF 15mm, MDP 15mm Porta com vidro: não Gaveta com trava: não Prateleiras: não possui Pés: fixos altos Com pia: não Quantidade de gavetas: 2 Acabamento: Pintura UV Tipo de fixação: Minifix e Cavilhas Conteúdo da Embalagem: Aparador Artely Trama com 2 gavetas 110cm de largura; Kit ferragem; Manual de montagem Dimensões: Altura (cm): 80 Largura (cm): 110 Profundidade (cm): 33 Garantia do Fabricante: 3 Meses Atenção: Foto meramente ilustrativa Entrega do Produto: Não nos responsabilizamos pela instalação/montagem, orientamos que este produto seja montado por um técnico de sua confiança, após a sua entrega, Não nos responsabilizamos pelo transporte por escadas/elevadores, guincho ou içamento deste produto.', 399.0, 399.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134201-820lj-mqynnaxf03d04d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58206344746', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999494014', 'Papete Infantil Disney Easy Grendene Kids 23160', 'A Papete Infantil Disney Easy Grendene Kids 23160 é perfeita para os pequenos aventureiros! Com um design inspirado nos personagens da Disney, ela traz diversão e conforto para os pés das crianças. O calçado é desenvolvido com materiais de alta qualidade e durabilidade, garantindo um ótimo desempenho durante as brincadeiras. Além disso, possui solado antiderrapante e fechamento ajustável, proporcionando segurança e praticidade. Ideal para acompanhar os pequenos em todas as suas aventuras!. MODELO: 3293160 REFERENCIA: 23160 MARCA: Grendene Kids MATERIAL DA PALMILHA: Borracha MATERIAL DA SOLA: PVC DETALHES: Fechamento por fita duplamente aderente GÊNERO: Male GRUPO DE IDADE: Infant MATERIAL DO SAPATO: PVC ESTILO: Urbano TIPO: SANDÁLIA', 90.99, 90.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7rdyu-m0wm9yu113sq0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F18999494014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
