INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993524530', 'Troninho Musical Prime Baby Fazendas', 'Troninho Musical Prime Baby Fazenda O troninho musical Prime Baby é ideal para auxilar os pequenos na fase de desfralde. Produzido com material resistente, com alças giratórias e depósito removível. Os troninhos são essenciais para o momento de independência do bebê, oferecendo tudo que o pequeno irá precisar, como segurança, conforto e diversão. Informações Adicionais:Tamanho: Único Referência: 1101-B Marca: Prime Baby', 159.9, 79.95, NULL, 'Mom & Baby > Diapering & Potty > Potty Training & Commode Chairs', 'https://cf.shopee.com.br/file/sg-11134201-7repq-m2i4tawsmi228c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22993524530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43662012538', 'Máquina de Solda Multiprocessos 205A Monofásica 220V Solda Gás - V8 Brasil', 'Loja do Mecânico - O que você precisa, nós temos! A máquina de solda Multiprocessos é um equipamento que permite realizar diferentes tipos de soldagem utilizando um único equipamento. Isso é possível porque ela é capaz de fornecer diferentes tipos de corrente elétrica, que são utilizados para soldar diferentes materiais e em diferentes posições. Pode ser utilizada para realizar soldagem MIG, TIG, eletrodo revestido, arco submerso, entre outras. Cada tipo de soldagem tem suas próprias características e exige habilidades e conhecimentos específicos do soldador. A máquina de solda Multiprocessos é uma opção muito versátil para quem precisa realizar diferentes tipos de soldagem e não quer investir em equipamentos específicos para cada tipo. Além disso, a máquina é compacta e fácil de transportar, o que a torna uma boa opção para quem precisa trabalhar em diferentes locais. Características: - O modelo 205i possui um sistema manual de regulagem da corrente de saída e de tensão, com botão de seleção das funções MIG/MAG, TIG seca e Eletrodo Revestido. - A versatilidade de operação e o fácil transporte desse equipamento permitem que você esteja sempre acompanhado de uma máquina de qualidade quando for necessário. - Comporta arames de até 5Kg com diâmetro de 0,8mm até 1,0mm. - Acompanha rodas que facilitam no transporte. Especificações Técnicas - Monofásica, com 220V. - Peso: 19,8Kg - Roldana de 0,8mm e 1mm - Proteção IP21. - Derrete eletrodos E6013/E7018 de até 3,25mm. - Solda com gás e sem gás. Conteúdo da Embalagem - 01 Máquina de solda - 01 Tocha MIG/MAG de conexão euro - 01 Tocha para Eletrodo - 01 Grampo terra Importante - Garantia de 12 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 2079.99, 2079.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-md637xzcbkdic3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F43662012538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698123672', 'Meia Selene Feminina Sapatilha Antiderrapante Pilates Com Viés 7850', 'Aproveite as aulas de Pilates com conforto e estilo! Feita em modelo Sapatilha, possui viés para melhor ajuste e conforto. Confeccionada em algodão e poliamida, ela proporciona um toque macio, além de contar com proteção antiderrapante na sola. Aproveite e treine com liberdade com a Selene.', 39.89, 27.88, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7qvea-lj07tj542lfb45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22698123672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200946725', 'Chinelo Kenner Masculino Kivah Pro Dots', 'A nova K-Pro chegou para redefinir o conceito de sandália robusta. Repaginada e ainda mais imponente, ela traz uma palmilha exclusiva, desenvolvida para proporcionar máximo conforto e desempenho em qualquer situação. Seu cabedal foi redesenhado com tiras tramadas em padrão quadriculado, que oferecem um toque macio, acabamento hidrorepelente e visual moderno. A palmilha termoconformada se ajusta aos pés, garantindo uma sensação superior de conforto a cada passo. O solado tratorado em borracha vulcanizada completa o conjunto com aderência e resistência excepcionais, tornando a K-Pro uma escolha certeira para quem busca estilo, inovação e estabilidade em um só modelo. Garanta já a sua!', 259.89, 196.88, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-8260r-ml88uqcyf7yn12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F58200946725', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394178426', 'Teclado para Notebook Samsung NP300E4C', 'Teclado compatível com Samsung NP300E4C O teclado compatível com Samsung NP300E4C foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Samsung. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: NP300E4C Moldura: Sem Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC191-REC-0083 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: NP300E4C, NP300E4C-AD5BR, NP300E4A, NP300E4C-AD4BR, NP300E4A-BD1BR, NP300E4A-BD2BR, NP305E4A-AD1BR, NP300E4C-AD1BR, NP300E4A-BD3BR, NP300E4A-AD1BR, NP300E4C-AD7BR, NP300E4A-B02JM, NP300V3A, NP300E4A-SD2BR Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 71.53, 46.74, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqsh4hm932ff58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23394178426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098699344', 'Conector DC Jack para Notebook Acer Aspire ES1-572', 'Conector DC Jack compatível com Acer Aspire ES1-572 Este é um DC Jack bringIT compatível com o notebook Acer Aspire ES1-572. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Acer. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 5.5mm x 1.7mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC122-AC-0004', 34.75, 33.02, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-825as-mqs15c5z864t2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22098699344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
