INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493331932', 'Protetor de teclado Ideapad 320 (15) 15.6" para notebook Lenovo', 'Protetor de teclado para notebook Lenovo Ideapad 320 (15) 15.6" Proteja o teclado do seu notebook com esta película protetora de silicone. Disponível em dois formatos, o protetor é fino, antideslizante e feito em material transparente, que não afeta a visibilidade do teclado nem a digitação. Em dois tamanhos, ela tem o formato ideal para cobrir todas as teclas de notebooks e ultrabooks. A película protege de acidentes com água e outros líquidos no seu teclado, além de proteger da poeira e outras sujeiras, sendo antibactericida e deixando seu notebook mais limpo e sempre higienizado. O uso da proteção também evita o desgaste das teclas e das impressões dos números, letras e caracteres. Ela é termoestável e à prova de queimaduras, isto é, não se deforma com o calor. Fácil de limpar, pode ser lavada e amassada diversas vezes sem perder o formato ou suas características originais e seu uso não afeta o resfriamento do notebook. Características do produto Feito em silicone transparente, não atrapalha a digitação Protege contra poeira, líquidos e outras sujeiras Resistente ao calor Maleável, dobrável e leve Pode ser lavado com água Dimensão: 34cm x 11cm Garantia: 3 Meses de Garantia Contra Defeitos de Fabricação Referência: AC115', 16.16, 16.16, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-824gt-mpv95mdj77d77c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23493331932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
