INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252996560', 'Shampoo e Condicionador Select Care Pós Química', 'Hidratação e nutrição para fios saudáveis e com brilho O Combo Select Care une a limpeza suave do shampoo com o condicionamento profundo do condicionador para garantir cabelos hidratados, nutridos e protegidos diariamente. Ideal para todos os tipos de cabelo, incluindo fios quimicamente tratados ou em transição, essa dupla promove maciez, vitalidade e brilho intenso, mantendo a saúde capilar por muito mais tempo. Principais Benefícios Limpeza eficaz sem ressecar. Hidratação profunda e nutrição duradoura. Proteção contra agressões externas e ação antioxidante. Fios mais resistentes, macios e com movimento natural. Brilho intenso e redução do frizz. Ativos Óleo de Coco: hidrata profundamente, reduz o frizz e repara pontas duplas. Ácido Lático: restaura a umidade perdida e promove brilho e maciez prolongados. Colágeno Hidrolisado: fortalece os fios, devolvendo elasticidade e resistência. Lumini System: melhora a absorção de nutrientes, prolonga a hidratação e protege a fibra capilar. Modo de Uso Com os cabelos úmidos, aplique o Shampoo Select Care, massageando suavemente ate formar espuma. Enxágue e, se necessário, repita a aplicação. Retire o excesso de água e aplique o Condicionador Select Care do comprimento às pontas. Deixe agir por 1 a 2 minutos e enxágue bem. Resultados Esperados Uso contínuo garante fios limpos, hidratados, macios e com brilho intenso, alem de uma proteção extra contra os danos externos do dia a dia.', 92.9, 92.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820mh-moiafycx80795f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703142099%2F58252996560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
