INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255531621', 'Filtro De Combustivel Fiat Toro 2.0 Diesel 2016 2017 2018 19', 'FILTRO DE COMBUSTÍVEL ORIGINAL MAHLE COM NOTA FISCAL E GARANTIA CONTÉM: 1 FILTRO DE COMBUSTÍVEL DIESEL MODELOS E ANOS COMPATÍVEIS: FIAT TORO 2.0 16V DIESEL 2016 EM DIANTE JEEP COMPASS 2.0 16V DIESEL 2016 EM DIANTE RENEGADE 2.0 16V DIESEL 2015 EM DIANTE GARANTIA DO FABRICANTE 90 DIAS IMPORTANTE - Vendemos somente produtos novos com nota fiscal na embalagem e garantia de fábrica. - Economize no Frete, adicione vários produtos ao carrinho de compras. - Temos uma Equipe Especializada para atendimento e suporte técnico. - As especificações e informações técnicas descritas no anúncio são de responsabilidade do fabricante. - Algumas das imagens podem ser meramente ilustrativas. Trabalhamos apenas com produtos de primeira linha, ou seja, a QUALIDADE, ACABAMENTO, DURABILIDADE e EFICÁCIA são sem sombra de dúvidas INCOMPARÁVEIS.', 144.3, 144.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-81ztw-mky6k5or63uo31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1612555968%2F58255531621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7158471964', 'Filtro Ar Condicionado Classe Slk 55 250 200 Akx 3578 Wega', 'FILTRO DE AR CONDICIONADO AKX 3578 WEGA - Sobre a marca : A Wega imprime qualidade à sua marca utilizando-se do que há de mais moderno mundialmente em tecnologias, processos e matérias-primas no desenvolvimento de seus produtos. Os produtos Wega seguem rigorosamente todas as especificações das montadoras de veículos nacionais e importados, o que garante a performance ideal exigidas em cada projeto de motor. - Porque deve-se trocá-lo regularmente? A troca regular do Filtro de Ar de Cabine garante um ambiente saudável aos ocupantes do veículo, pois evita a invasão de contaminantes como: poeiras, ácaros e outros micro-organismos nocivos que atacam as vias respiratórias do ser humano. - Aplicação : Mercedes Benz : Classe SLK 200 1.8 Kompressor 2004 até 2012 Classe SLK 250 1.8 CGI 2012 Em Diante Classe SLK 350 3.5 2004 até 2014 Classe SLK 55 5.5 V8 AMG 2004 Em Diante - Marca: WEGA - Modelo : Akx 3578 - Tipo de Filtro : Filtro De Ar Condicionado - Conteúdo da embalagem : 1 Unidade - Elemento Filtrante: Non Woven - Formato : Retangular - Comprimento : 362 mm - Altura : 35 mm - Largura : 178 mm - Cor : Branco - Estrutura de Reforço: ​Feltro Garantia de 90 Dias contra defeitos de fabricação . ATENÇÃO : Antes de efetuar a compra, nos comunique através do suporte o ano e modelo do seu veículo para que possamos enviar o filtro correto. A Martinense de pneus recomenda a instalação por um profissional qualificado, e sugerimos seguir a especificações manual do veículo/Equipamento, se ausentando de qualquer dano causado por instalação inadequada e mau uso do produto.', 66.09, 66.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/6363fdd97427a0c