INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792475062', 'Joelheira Articulada Proteção Jet Adenture Apache Mountain Bike Downhill Moto Motocross Trilha Enduro Skate Patins', 'Joelheira Jet Motocross Apache Downhill Trilha Enduro Bike A Joelheira é um equipamento fundamental para práticas de Motocross, Downhill, Velocross, Motocross, Trilha e outros. Garanta segurança para proteção de seu joelho e canela juntando conforto e qualidade! A joelheira vem em tamanho único e possui fechamento em 3 tiras de fitas autocolantes para ajustar para todos os tamanhos adultos necessários assim evitando que fique solta da perna. - Peso: 465gr aproximados.- Comprimento: 42 centímetros. * Observações: -Anuncio trata-se 1 par de joelheira jet motocross apache. - Imagem ilustrativa. Produto novo!- Compra 100% segura! - Garantia 90 dias', 115.9, 62.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-lm7s35bczlxs87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F23792475062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
