INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898876589', 'Alicate de Pressão Mordente Triangular 10'''' Tramontina PRO', 'Prende, trava e não solta! Esta é a principal característica do alicate de pressão da Tramontina PRO que auxilia na fixação de peças que serão cortadas, lixadas ou soldadas, por exemplo. A ferramenta certa para você que precisa de resistência e segurança. Mordentes forjados em aço cromo vanádio. Corpo formado por chapas conformadas.Acabamento cromado.Abertura regulável.Possui alavanca para destravar.Possui mordentes com perfil triangular.Os alicates de corte são testados quanto à resistência ao desgaste do gume de corte em máquina de ensaio específica.Os alicates possuem dureza diferenciada no gume de corte e no corpo.Segurar, puxar e prender peças firmemente.Em trabalhos leves pode ser usado como uma prensa.As ferramentas são produzidas e testadas conforme normas específicas. Prende, trava e não solta! Esta é a principal característica do alicate de pressão da Tramontina PRO que auxilia na fixação de peças que serão cortadas, lixadas ou soldadas, por exemplo. A ferramenta certa para você que precisa de resistência e segurança.', 64.21, 64.21, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-lkuygghfhtfs42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F20898876589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
