INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23991138248', 'Hidratante Facial Neutrogena Hydro Boost Water Gel FPS 25 40g', 'Um hidratante facial com Ácido Hialurônico, Vitamina C e FPS 25, combina 48 horas de hidratação intensa, ação antioxidante, e prevenção do envelhecimento precoce da pele. - Pele hidratada por 48h. - Restabelece os níveis saudáveis de água na pele ao longo do dia. - Exclusiva tecnologia HELIOPLEXTM: proteção ampla e eficaz contra os raios UVA e UVB. - Ação antioxidante da vitamina C. - Fórmula com textura water gel: não deixa a pele oleosa - Dermatologicamente testado, hipoalergênico* e oil free. * Formulado de maneira a prevenir o surgimento de alergias. - Hidratação com proteção solar e vitamina C. - Proteção solar para prevenir o envelhecimento da pele. - Textura ultraleve de rápida absorção.', 123.29, 123.29, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7qve0-lge6tdt8ljb991', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F818390117%2F23991138248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
