INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43725372715', 'Chinelo Modare Ortopédico Esporão Massageador Conforto 7142 Preto', 'O Chinelo Modare 7142 é ideal para quem busca alívio, conforto e leveza no dia a dia 👣. Desenvolvido com tecnologia ortopédica e palmilha massageadora, ajuda a estimular a circulação e a reduzir o impacto, sendo perfeito para quem sofre com esporão, fascite plantar ou dores nos pés. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/42423026701/ 💎 Destaques 👣 Palmilha massageadora: com bolhas que proporcionam relaxamento e bem-estar 🌿 Design anatômico e ortopédico: melhora o apoio e reduz a pressão nos pés ☁️ Tiras elásticas cruzadas que se ajustam com suavidade 🩰 Solado leve e antiderrapante, ideal para uso prolongado 💖 Produto original Modare Ultraconforto, com qualidade e durabilidade 📋 Ficha Técnica Marca: Modare Ultraconforto Modelo: 7142 Tipo: Chinelo feminino ortopédico Material externo: Tecido elástico tramado Palmilha: Massageadora Ultraconforto Solado: Borracha leve e antiderrapante Altura do salto: 4 cm (aprox.) Estilo: Casual / Ortopédico / Confortável Numeração: 33 ao 40 🧼 Dicas de Limpeza Lavar com pano úmido e sabão neutro Não deixar de molho Secar à sombra 📏 Tabela de Medidas (aproximada) 33 → 21,5 cm 34 → 22,0 cm 35 → 22,5 cm 36 → 23,0 cm 37 → 24,0 cm 38 → 24,5 cm 39 → 25,0 cm 40 → 25,5 cm', 99.9, 69.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg3qd8o1o8w516', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F43725372715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11747614914', 'Meia HUPI Longa Oceano', 'Conforto, design, tecnologia e qualidade são adjetivos que descrevem perfeitamente as meias cano alto. Testadas e aprovadas por atletas de diversas modalidades, a meia cano alto é um item indispensável para você. Praticar esportes com conforto e máximo desempenho é o seu objetivo, e também o nosso. Por isso a meia apresenta diversos destaques que fazem dela um item fundamental. O material utilizado na fabricação da meia é importado da Alemanha. Os fios de elastano e poliamida formam um conjunto cheio de vantagens. O principal destaque é o conforto, proporcionado pela transpiração que a meia cano alto oferece, deixando os pés secos e bem protegidos. A combinação da matéria prima assegura a flexibilidade oferecendo maior liberdade de movimento, sem que a peça laceie, perdendo sustentação. Na região dos dedos e calcanhar, os fios são dispostos em direções diferentes do restante da meia, fazendo com que a modelagem se torne muito mais anatômica, acompanhando o desenho dos pés. Esta característica também prolonga HUPI a durabilidade, impedindo o desgaste. Clique Aqui e confira toda linha de meias cano alto da HUPI! Estilo até o joelho (meia cano alto), cano com 30cm de comprimento; Tamanho único - veste do tamanho 36 ao 42; Unissex; Composição: 97% Poliamida | 3% Elastano. ATENÇÃO: As cores podem apresentar diferenças em tonalidade conforme a calibragem do monitor.', 97.84, 74.9, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/br-11134207-820l6-mlz9dr6preo6f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F11747614914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
