INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4083215664', 'Legging Masculina Térmica Lupo 70054-001', 'Características: Calça masculina Térmica Underwear Warm. Desenvolvido com tecnologia sem costura (Seamless Dry), diminui os pontos de fricção. Possui ventilação estratégica, colocada em zonas criticas de suor,proporcionando alto conforto térmico. Tecido com tratamento (Sanitized Actifresh) de higienização que impede a proliferação de microrganismos e bactérias causadores de odores. Produtos térmicos agem estabilizando a temperatura corporal durante praticas esportivas. Produtos Warm confeccionado com Fio Heat desenvolvido com aditivo de cascas de café carbonizadas que, através da nanotecnologia retarda a troca de calor do corpo em temperaturas externas baixas. Composição: 96% Poliéster e 04% Elastano.', 193.8, 193.8, NULL, 'Men Clothes > Innerwear & Underwear > Thermal Innerwear', 'https://cf.shopee.com.br/file/sg-11134201-22110-xpv1l2sp6yjv64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F4083215664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
