INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205665912', 'Sapatilha Infantil Molekinha 21061073', ',schutzA sapatilha infantil feminina Molekinha 21061073 é perfeita para as pequenas fashionistas! Confeccionada em materiais de alta qualidade, garante conforto e durabilidade para o dia a dia das crianças. Com design charmoso e moderno, é um calçado versátil que combina com diferentes looks. Ideal para acompanhar as atividades das meninas com estilo e delicadeza. Confira agora mesmo e garanta esse lindo calçado para a sua princesa!. MODELO: 0441073 REFERENCIA: 21061073 MARCA: Molekinha MATERIAL DA PALMILHA: PU MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GÊNERO: Female GRUPO DE IDADE: Infant MATERIAL DO SAPATO: Verniz Premium Altura do Produto: 9 Largura do Produto: 14 Comprimento do Produto: 19 Peso do Produto: 255.000', 90.99, 90.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Flats', 'https://cf.shopee.com.br/file/sg-11134201-82602-ml2bhhfjfockb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F58205665912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
