INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21431572509', 'Esponja Poliester Loucas Multiuso Kit 10 Uni Flash Limp', 'Seja bem-vindo(a) ao nosso canal de vendas! Temos como objetivo a satisfacao de nossos clientes e a missao de atender bem, trabalhando com profissionalismo nas vendas e no atendimento. Proporcionando assim uma otima experiencia de compra! A Esponja Multiuso Poliester da FlashLimp e composta a partir de revestimento de malha poliester, proporcionando que, durante a lavagem, nao risque os utensilios domesticos, aumentando o tempo de vida util deles. A esponja e indicada para limpeza leve como vidros, cristais, porcelanas, aco inox e antiaderentes. Conserve todas as pecas da sua cozinha com material de qualidade. A Esponja Multiuso Flashlimp de Poliester tem alta durabilidade. Antes de utilizar, verifique se a esponja esta limpa, pois particulas de sujeira podem riscar a superficie dos utensiliios. Lave imediatamente apos o uso e deixe secar. Guarde o produto em local seco ao abrigo da luz solar. ITENS INCLUSOS: - 1 Esponja Caracteristicas: - Esponja Multiuso Poliester da FLASH LIMP e composta a partir de revestimento de malha poliester - Esponja e indicada para limpeza leve como vidros, cristais, porcelanas, aco inox e antiaderentes - E lavavel, nao retem odores e nao risca Medidas e peso: C-11cm L-7cm A-3cm - 11g Aguardamos sua compra e esperamos que tenha uma otima experiencia! Conte conosco! Sera um prazer lhe atender!', 38.9, 38.9, NULL, 'Home & Living > Home Care Supplies > Sponges & Scouring Pads', 'https://cf.shopee.com.br/file/635b806c0f46b25a690ceab6c1be698c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F741045633%2F21431572509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393589106', 'Lomiss Piercing Septril Rook Conch Nariz Meia Argola Titânio Segmento Articulado Zircônia', '💖 💖 🥳 🥳 Bem-vindo a 《LOMISS Piercing》🥳 🥳 💖 💖 🎊🎊👍👍Somos uma grande empresa de piercing. O endereço está localizado em São Paulo.Todos os produtos da loja são de alta qualidade. 👍👍🎊🎊 🚚 🚚🚀 🚀 Temos uma grande quantidade de estoque. Enviaremos seu pedido em até 24 horas após o pagamento. 🚀 🚀🚚 🚚 🎉🎉🎫 🎫Clique em """"SEGUIR"""" e receba vouchers de desconto exclusivos.🎫 🎫🎉🎉 ---------------------------------------------------------------------------------------------------------------- ⭐⭐O produto é 100% titânio puro. Absolutamente sem alergias!! ⭐⭐Características:Resistente à corrosão, alta resistência, Inibição de bactérias, não alergênico！ 💎- Espessura Da Haste: 1.2/1.0mm 💎- Diâmetro da argola: 8/10 mm 💎- Material: Titânio 100% 💎- Pedra: Zircônia 💎- Fecho: Segmento Articulado 💎- Podendo ser Usado: Septril, Rook, Conch, Nariz 💎- Quantidade: 1 unidade Lembrando que: Cada pessoa tem formato de corpo / local de aplicação (mais pra dentro/fora), então varia com tamanho de joia. Fácil Colocação e Remoção *PVD - É uma tecnologia utilizada para a deposição de filmes metálicos finos sobre diversos tipos de substratos. O processo é realizado, sob vácuo, onde os metais a serem depositados são evaporados. É particularmente indicado para aqueles produtos inovadores e de qualidade que necessitam atender elevados padrões e permite ainda obter uma vasta gama de cores. - Elevada resistência ao desgaste e abrasão; - Resistência ao suor e transpiração humanos; - Hipoalergênicos.', 81.76, 43.88, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rffy-m3uk7meane71ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduc