INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499886168', 'Catraca Reversível 1/2" Vonder Cabo Emborrachado', 'Catraca Reversível para Soquete 1/2" – Vonder com Cabo Emborrachado A Catraca Reversível Vonder 1/2" é ideal para profissionais e hobbystas que buscam praticidade e eficiência na fixação de porcas e parafusos. Produzida em aço cromo vanádio, garante durabilidade e resistência em trabalhos pesados. O cabo emborrachado oferece maior conforto e firmeza durante o uso, enquanto o mecanismo reversível permite apertar e afrouxar rapidamente, sem perder tempo. Itens Inclusos 1 Catraca reversível para soquete Vonder Especificações Técnicas Material: Aço cromo vanádio Acabamento: Niquelado e cromado Encaixe: 1/2" Comprimento total: 240 mm Torque máximo: 512 N.m Revestimento do cabo: Emborrachado Massa aproximada: 0,557 kg Garantia legal: 90 dias Por que escolher este produto? Produto novo e original Vonder Pronta entrega e envio em até 24 horas Compra 100% segura Estoque limitado – garanta já a sua', 89.9, 89.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824j2-meiwx5n09eyv13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F18499886168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198000395', 'Chave Para Esmerilhadeira Multiplas Medidas Bestfer', 'A Chave Para Esmerilhadeira Múltiplas Medidas Bestfer é a ferramenta essencial para quem busca praticidade e eficiência na troca de discos. Com um design inovador em forma de "Y", ela se adapta a diferentes tamanhos, tornando-se indispensável em qualquer kit de ferramentas. Fabricada com aço de alta resistência, garante durabilidade e proteção contra corrosão. Seu cabo antiderrapante proporciona uma pegada firme e confortável, reduzindo o risco de escorregamentos durante o uso. Além disso, sua compatibilidade com diversas marcas e modelos de esmerilhadeiras a torna uma escolha versátil para profissionais e amadores. Vantagens: - Fabricada em aço de alta resistência - Cabo antiderrapante para maior segurança - Design versátil em forma de "Y" - Compatível com múltiplos modelos de esmerilhadeiras -Leve e compacta, fácil de transportar Especificações técnicas: Marca: Bestfer Material: Aço Design do Cabo: Antiderrapante Formato: Forma de Y Conteúdo da embalagem: 1 Chave Para Esmerilhadeira Bestfer Garantia: - 3 meses de garantia', 41.9, 27.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4ubytqogsz6ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F21198000395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193989303', 'Chave Phillips Profissional - Tramontina', 'A chave Phillips Tramontina é a ferramenta ideal para quem busca segurança, precisão e resistência ao trabalhar com parafusos cruzados. Com ponta usinada para garantir encaixe perfeito e reduzir o risco de espanar o parafuso, ela proporciona maior controle e eficiência em cada aperto ou desaperto. Fabricada em aço cromo vanádio de alta qualidade com ponta temperada magnetizada, a chave oferece durabilidade superior, resistência à corrosão e praticidade no manuseio, mantendo o parafuso firme na ponta durante o uso. Seu cabo ergonômico com design anatômico proporciona conforto e firmeza, mesmo em usos prolongados. Vantagens: Ponta magnetizada para segurar o parafuso com mais segurança Encaixe preciso em parafusos tipo Phillips Cabo ergonômico com ótimo grip, confortável para uso contínuo Aço cromo vanádio resistente com acabamento niquelado ou cromado Ideal para manutenção geral, montagem, reparos e eletrônica Dados Técnicos: Marca: Tramontina Material: Aço cromo vanádio temperado Ponta: Phillips magnetizada, usinada com precisão Cabo: Ergonômico em polipropileno ou PVC (varia por modelo) Aplicação: Parafusos com fenda cruzada (Phillips) Uso: Profissional e doméstico Tamanhos Disponíveis: 1/8 x3” – 1/8 x4” 1/8 x5” – 1/8 x6” 3/16 x3” – 3/16 x4” 3/16 x5” – 3/16 x6” 1/4 x4” – 1/4 x5” 1/4 x6” – 1/4 x8” 5/16 x6” – 5/16 x8” 5/8 x8” As chaves Phillips Tramontina oferecem qualidade profissional, ergonomia e alto desempenho para todos os tipos de serviço.', 34.9, 23.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfhd-m9j28jevr6io21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22193989303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
