INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22319827258', 'Tacho Antiaderente Frigideira Profissional Grande Teflon 28 cm Tampa de Vidro', 'A panela WOK é uma queridinha da cozinha moderna, ideal para um estilo de vida saudável, pois cozinha rapidamente preservando as propriedades dos ingredientes, como legumes picadinhos. Confira 4 jeitos de utilizar a Frigideira Wok 26cm Antiaderente Cozillar: cozinhar, saltear, fritar ou preparar alimentos no vapor. Complete seu jogo de panelas com esse item indispensável. Descrição: Diâmetro: 28,0 cm. Largura Total: 41 cm (alça/alça) Largura: 30 cm Altura: 8 cm Peso Frigideira: 0,566 Kg Peso com Tampa: 1,257 kg Capacidade Volumétrica: 3,3 L (valor aproximado) Espessura 1.70 cm Pomel pode sofrer alteração de acordo com a disponibilidade do estoque. Recomendações de Uso : A capacidade volumétrica máxima para cozimento é de 3/4 da capacidade total da peça. Produto destinado a utilização de fogão a gás', 93.9, 63.5, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-7qve4-lfzfsvmng5z72b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379103154%2F22319827258', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18065063403', 'Cadeira de Alumínio Reclinável Boreal Anis Tela em Poliéster Revestido em PVC MOR', 'Cadeira de Alumínio Reclinável Boreal Anis Tela em Poliéster Revestido em PVC MOR - Dobrável, ocupa pouco espaço e de fácil transporte; - Encosto mais largo e alto; - Sapatas de proteção e braços plásticos com porta-copos; - Sem travessa na parte frontal do assento, oferecendo maior conforto; - Sugestão de uso: praias, varandas, sala de estar, Camping e praças; - Ideal para regiões litorâneas; - Estrutura em alumínio, proporcionando maior leveza e resistência; - Reclinável em até 4 posições; - Braços plásticos; - Tela em sannet liso, com proteção UV, anti-mofo e de fácil limpeza; - Altura do assento: 41cm; - Largura do assento: 49,5cm. ESPECIFICAÇÕES TÉCNICAS: Capacidade (kg): 110 Material da estrutura: Alumínio Material tela: Poliéster com revestimento em PVC Dobrável: Sim Reclinável: 4 posições Peso (kg): 2.41 Referência: 2169 BOREAL ANIS Dimensões (AxLxP): 97 x 64 x 73cm Itens Inclusos: - 1 Cadeira Alumínio Reclinável Mor - 1 Manual do Produto Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Garantia Fabricante: 3 meses', 314.9, 314.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-22110-y038bnm8vbkv0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889942432%2F18065063403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
