INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10583699532', 'Bermuda Térmica Unissex Gold II 03800 Poker Azul Gg', 'Confeccionada em malha na proporção exata de poliéster e elastano com proteção UV FPS 50+. Ela garante excelente resistência mecânica e elasticidade na medida ideal, proporcionando ao atleta maior conforto e mobilidade durante a prática esportiva. Além disso, sua modelagem anatômica, justa ao corpo, ajuda a diminuir o atrito, consequentemente, melhora a eficiência e sua dinâmica no alongamento extenso, sem perder a forma original. Térmica poliamida elastano Confortável ao vestir. Modelo Unissex. Medidas Aprox.: P: refere-se ao 38 M: refere-se ao 40 G: refere-se ao 42 GG: refere-se ao 44 P: 28 cm x 40 cm (LxA) M: 30 cm x 43 cm (LxA) G: 34 cm x 45 cm (LxA) GG: 36 cm x 47 cm (LxA) Conteúdo da Embalagem: 01 un. Bermuda Térmica Unissex Gold II 03800 Poker Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagens Meramente Ilustrativas.', 69.0, 69.0, NULL, 'Men Clothes > Shorts', 'https://cf.shopee.com.br/file/6ea001d59304f71af74cdffae00b8803', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F10583699532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
