INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794388014', 'Caixa Direção Mecânica Elétrica Nova Fiat Argo E Cronos 1.0 1.3 1.8 Todos 2018 Em Diante', 'Bem vindo!! Você está em uma loja especializada em soluções automotivas seguras e confiáveis. Aqui, cada detalhe é pensado para cuidar do que move você: sua família, sua segurança e seus melhores momentos na estrada. 🚗 Dirigibilidade Renovada e Precisa para Seu Fiat Argo e Cronos! 🛠️ Transforme sua experiência ao volante com a Caixa Setor de Direção Elétrica da Genuine Automotive, referência em excelência no mercado de autopeças. Acompanha axiais (medida M15X1,5mm) e coifas, garantindo um conjunto completo e pronto para instalação no seu Fiat Argo ou Cronos. Fabricada com tecnologia de ponta e submetida a rigorosos padrões de qualidade, esta peça oferece segurança, desempenho e durabilidade superiores para seu veículo. 🔧 Especificações Técnicas: Marca: Genuine Automotive Condição: Produto novo Garantia: 6 meses Acompanha: Axiais (M15X1,5mm) e coifas 📎 Códigos de Referência Compatíveis: 31591, 52044919, 52044921, 00520449190, 7146515910 🚘 Compatibilidade Garantida: Compatível com os seguintes modelos Fiat: Argo 1.0, 1.3 e 1.8 — 2018 a 2022 Cronos 1.0, 1.3 e 1.8 — 2018 a 2022 ✅ Benefícios ao Adquirir Este Produto: ✨ Alta Qualidade Genuine Automotive: Produzida por líder no setor, garantindo durabilidade e desempenho superior. 🔧 Direção Suave e Precisa: Melhora a resposta e proporciona uma condução mais confortável e segura. 🧩 Compatibilidade Perfeita: Projeto específico para seu Fiat, assegurando instalação sem problemas. 🛡️ Garantia de Tranquilidade: 6 meses de garantia para sua segurança e confiança. 📦 Conteúdo da Embalagem: 1 Caixa Setor de Direção Elétrica Acompanha: Axiais (M15X1,5mm) e coifas 📌 Recomendações e Regras de Garantia: ⚠️ Instalação Profissional Obrigatória: Essencial para preservar a garantia e garantir a durabilidade do produto. 🔍 Troca em Garantia: Envio de novo produto após análise técnica e constatação do problema. 🛠️ Cobertura de Mão de Obra: Garantia válida apenas para o produto, custos com instalação não incluídos. ❓ Dúvidas? Use o campo de perguntas abaixo ou fale com nossa equipe especializada! 🎯 Garanta já o melhor para seu Fiat! Adquira sua Caixa Setor de Direção Elétrica Genuine Automotive para Argo e Cronos em nossas lojas oficiais – Camillo Parts, Genuine Automotive ou Edumac Parts – e tenha a certeza de estar comprando qualidade, confiança e suporte técnico garantido! 🛒💯', 811.89, 811.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-8262l-mk9u7h2kzksg84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F23794388014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993689713', 'Kit Aditivo Protetor Radiador Ps2G Rosa Radiex 4 Litros', 'NUM.PEÇA: R1892 VALOR REFERENTE Á: 4 Litros Kit Aditivo Radiador Rosa R1892 - RADIEX INFORMAÇÕES Bio Coolant Pronto Uso Rosa PS2G - R1892 Praticidade e proteção para o ano todo O aditivo PS2G - R1892 é um composto químico desenvolvido com polímeros de alta performance, PRONTO PARA USO, que oferece proteção total aos componentes metálicos do sistema de arrefecimento de motores de linha leve, pesada e estacionários, prolongando a vida útil do motor, evitando a corrosão, a cavitação e o ressecamento das mangueiras. Diluição de 40% a 60% PRONTO USO 1 ano no sistema Biodegradável Modo e recomendações de uso: Antes de colocar o Protetor PS2G - R1892 no radiador, execute a limpeza completa no sistema de arrefecimento com água pura. Em caso de excesso de sujeira, recomenda-se a aplicação do Limpa Radiador Radiex R-9301. Aplique o PS2G - R1892 até completar o nível indicado no reservatório. Ex.: Para um sistema com capacidade de 5 Litros, colocar 5 Litros do PS2G. Preencher todo o sistema com o produto puro, sem adicionar água. Efetue a substituição do produto no sistema a cada 1 ano. ATENÇÃO: Utilize o produto puro no sistema. Não misture com outros fluídos ou soluções. Disponível nas embalagens de 1, 5, 20, 50 e 200 Litros.', 137.02, 137.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rbl4-m62qlkofvx3sae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1386520276%2F23993689713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
