INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8737335058', 'Aromatizante Automotivo Areon Smile Bubble Gum O Melhor', 'Areon Smile e uma colecao contemporanea de aromatizantes que cativa seus sentidos. Com design harmoniosos e essencias cuidadosamente desenvolvidas, a Areon Smile proporciona sensacoes de bem estar prolongadas ao seu redor. - Perfeito para pequenos espacos - Papel embebido em perfume - A embalagem e usada para regulacao das fragrancias - Design desenvolvido para cada especifico perfume Caracteristicas Fragrancia: BUBBLE GUM Familia Olfativa: Adocicado Notas De Saida: Morango, fresco Notas De Coracao: Framboesa, maca, abacaxi, hortela, flor de laranjeira, violeta Dimensoes da Embalagem (C x L ): 0,19m x 0,07m Conteudo da Embalagem: 01 odorizador de ambiente de celulose Modo de usar: Abrir o envelope na parte superior e retirar uma pequena parte do odorizador, como mostrado na embalagem (1cm/semana) para ajustar a intensidade da fragrancia. Em seguida, pendurar livremente no lugar desejado. Durabilidade: ate 07 semanas. Alta Qualidade. COMPRE DIRETO DO DISTRIBUIDOR COM TOTAL GARANTIA NA ENTREGA E NO POS VENDA, TIRE SUAS DUVIDAS DIRETO COM PESSOAS ESPECIALIZADAS NO RAMO AUTOMOTIVO!!', 15.9, 15.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Fragrances', 'https://cf.shopee.com.br/file/9a32100bb22a72167bd2a9a8cf1a1333', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397020362%2F8737335058', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
