INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259038282', 'Nissin Miojo Lámen Carne', 'Nissin Lámen sabor Carne: refeição prática e saborosa pronta em apenas 3 minutos, ideal para quando bate aquela fome! Modo de Preparo: * Fogão: Ferva 450ml de água, junte o macarrão e cozinhe por 3 minutos. Retire do fogo e misture o tempero. * Micro-ondas: Coloque 450ml de água e o macarrão em um recipiente próprio para micro-ondas. Leve ao forno micro-ondas em potência alta por 5 minutos, interrompendo na metade do tempo para mexer. Retire do micro-ondas, misture o tempero e sirva em seguida.', 3.49, 3.49, NULL, 'Food & Beverages > Convenience / Ready-to-eat > Instant Noodles', 'https://cf.shopee.com.br/file/sg-11134201-825b2-mqnelmu4hr7kb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58259038282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
