INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22091413272', 'Conduíte ThermGuard 8mm Preto 180ºC / 1.5KV - Cód.7192', 'Espaguete-Camisa ThermGuard 1280 é uma luva tratada termicamente que fornece proteção superior contra calor conduzido e convectado, normalmente chamado de macarrão para alta temperatura. ThermGuard 1280 é composto por três camadas: • Uma camada interna de fibra de vidro trançada para fornecer isolamento superior aos componentes que deve manter temperaturas estáveis garantindo a eficiência e desempenho do equipamento a ser protegido. • Uma camada intermediária de aramida que aumenta a resistência à abrasão. • Uma camada externa de borracha de silicone revestida para agir como uma barreira contra poeiras, fluidos e para melhorar a flexibilidade. *Valor referente ao metro* O ThermGuard 1280 pode ser usado em linhas de combustível e hidráulicas, cabos e mangueiras proximidade de motores e sistemas de exaustão. Dados Técnicos: Diâmetro Interno: 8,00mm Temperatura de Trabalho: -50°C to +225°C Inflamabilidade: Auto Extinguível Isolação Elétrica: 1.5KV Cor: Preto', 21.82, 21.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-mcqdmuesjsaoe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F634548170%2F22091413272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
