INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693477947', 'Marca Texto Mini Fun Cis 6 Cores Neon – Ponta Chanfrada e Secagem Rápida', 'Apresentamos o Pincel Marca Texto Mini Fun Cis, — pensado para quem busca destacar anotações com diversão, praticidade e cores vibrantes. Compacto e cheio de estilo, é ideal para estudantes, profissionais e apaixonados por papelaria criativa. Características principais • Design mini com carinhas divertidas, perfeito para levar no estojo ou bolsa • Ponta chanfrada, que permite traços finos e largos • Tinta à base de água, com secagem rápida • Cores neon vibrantes, garantindo destaque e personalidade nas anotações • Compacto e prático, ideal para o uso diário Especificações técnicas Marca: Cis Produto: Pincel Marca Texto Mini Fun Tipo de ponta: Chanfrada Tinta: À base de água, com secagem rápida Cores: 6 cores neon vibrantes Formato: Mini, com design divertido Uso recomendado: Escolar, profissional e cotidiano Inclui na embalagem 1 estojo com 6 pincéis marca texto Mini Fun Cis (cores neon sortidas) Como usar / Ideal para Esse produto é recomendado para destacar textos, anotações e estudos, perfeito para estudantes, professores e profissionais que desejam organização e um toque de criatividade em suas anotações.', 74.43, 74.43, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-m1fnd0vyq05b7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306190243%2F22693477947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
