INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55406290878', 'Sandália Infantil Menina Kidy Gloss Belinha Brilho Fisherman Morderna Confortável Translúcida Leve', 'A Sandália Kidy Gloss é perfeita para as meninas que amam conforto com um toque delicado de brilho. Com acabamento translúcido em nude e base lilás, ela traz leveza, charme e um visual moderno para os dias mais quentes. Produzida em material macio e flexível, oferece ajuste confortável aos pés, acompanhando cada passo com suavidade. O fechamento com fivela lateral garante segurança e praticidade no calce. A palmilha confortável proporciona sensação agradável durante o uso, enquanto o solado texturizado contribui para mais estabilidade ao caminhar. Ideal para passeios, momentos em família e produções cheias de estilo, a Kidy Gloss combina: ✔ Material leve e flexível ✔ Ajuste seguro com fivela ✔ Conforto para o dia todo ✔ Solado com boa aderência ✔ Visual delicado e moderno Disponível do 25/26 ao 33/34. Kidy. Conforto e encanto em cada passo.', 119.99, 99.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mkwp48ur7g1z5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F55406290878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40074011854', 'Sandália Infantil Menino Kidy Fly Baby Marinho Dino Surpresa Confortável Anatômica Antiderrapante', 'Diversão e conforto andam juntos com a Sandália Kidy Fly Baby Marinho Gelo e Laranja. Desenvolvida especialmente para os primeiros passos, ela é anatômica, totalmente flexível e conta com solado em TR antiderrapante, garantindo segurança e estabilidade em cada movimento. O fechamento em fita adesiva facilita o calce, trazendo praticidade para os pais e autonomia para os pequenos. E tem mais: a sandália acompanha um super brinde exclusivo – Dino Surpresa Colecionável, que transforma o momento da compra em pura diversão e incentivo à imaginação. Kidy cuidando dos passos com carinho, inovação, conforto, estilo e aventura em cada passo. Formato Anatômico Sempre pensando na saúde e conforto das crianças, todos os calçados Kidy possuem formato anatômico que auxilia no crescimento e desenvolvimento saudável dos pés. Tamanhos: do 22 ao 27; Fechamento: Fita Adesiva; Cabedal: Sintético; Forro: Têxtil; Palmilha: EVA ; Sola: PVC;', 139.99, 119.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhghoq0xdjb7a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F40074011854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
