INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253762212', 'Blusa Cropped Feminina Estampada Endless Verde', 'A Blusa Cropped Feminina Estampada Endless é confeccionada em viscose khyara, proporcionando conforto e leveza. Com manga ampla, o design traz um toque descontraído e moderno. A estampa digital, vibrante e única, garante um visual arrojado. Na parte frontal e nas costas, o elástico ajusta a blusa ao corpo, oferecendo um caimento perfeito. Ideal para looks casuais e descontraídos, a peça é versátil e pode ser combinada com diversas opções de roupas.', 99.99, 94.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-825a8-mr1zlpll4ydi68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58253762212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
