INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54752878869', 'Par Farol Milha Vectra 2006 2007 2008 2009 2010 2011 Agile 2010 2011 2012 2013', 'Código do Produto: 127748 VALOR ANUNCIADO REFERENTE AO PAR - DIREITO + ESQUERDO Par Farol Milha Vectra 2006 2007 2008 2009 2010 2011 Agile 2010 2011 2012 2013 O farol de milha é uma peça essencial para visibilidade em vias noturnas ou em dias de neblina. Eles devem estar sempre em bom estado para maior segurança do motorista e seus ocupantes. Este item possui material de alta qualidade e resistência, composto com sua lente em acrilico que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Chevrolet - Vectra 2006 - Vectra 2007 - Vectra 2008 - Vectra 2009 - Vectra 2010 - Vectra 2011 - Agile 2010 - Agile 2011 - Agile 2012 - Agile 2013 Especificações Técnicas: - Lente Lisa - Foco Simples - Material da Lente em Acrilico - Material da Carcaça em Plástico - Suporta Lâmpadas de até 55w - Encaixe da Lâmpada H3 ATENÇÃO Garantia - 3 Meses O valor anunciado referente ao Par. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 182.08, 182.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-822xq-mi31elacedj54c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F54752878869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898793143', 'Par Amortecedor Dianteiro Lado Esquerdo Direito Strada 2001 A 2020', 'Par de Amortecedores Dianteiros Perfect para Fiat Strada APLICAÇÃO • Fiat Strada Sem Barra Estabilizadora anos 2001 a 2020 exceto versões Locker e cabine dupla ESPECIFICAÇÕES • Lado Dianteiro Par Completo LD e LE • Código AMD0122 • Marca Perfect • Medida mínima 384 mm por unidade • Medida máxima 546 mm por unidade • Peso total 8.30 kg 4.15 kg cada unidade • Embalagem por unidade 59 x 19.5 x 19.5 cm comprimento x largura x altura • Código de barras 7899152546923 • NCM 87088000 • Sistema Force Gas CÓDIGOS REFERÊNCIA • GP30120 34875G 338038 749011 SP176 SP182 HG33004 HG33093 467962770 51791068 51959492 VANTAGENS • Excelente desempenho e estabilidade na suspensão dianteira com instalação em par • Absorção uniforme de impactos para maior conforto na condução • Compatibilidade garantida com Fiat Strada sem barra estabilizadora • Instalação direta sem necessidade de adaptações • Construção robusta para maior durabilidade • Ideal para substituição original em par • Sistema Force Gas para melhor resposta da suspensão • Equilíbrio perfeito entre os dois lados do veículo INSTALAÇÃO • Elevar o veículo com macaco adequado e suportar com cavaletes de segurança • Remover ambas as rodas dianteiras • Desconectar conexões da suspensão que impeçam a remoção dos amortecedores • Retirar parafusos de fixação superiores e inferiores dos amortecedores antigos • Instalar os novos amortecedores posicionando corretamente as borrachas e coifas • Apertar todos os parafusos com torque especificado pelo fabricante do veículo • Verificar todos os componentes da suspensão dianteira após montagem • Testar o veículo em local seguro após instalação • Realizar alinhamento de direção após a troca CONTEÚDO • 2 Amortecedores Dianteiros Perfect AMD0122 Par Completo Lado Direito e Lado Esquerdo Produto novo acompanha nota fiscal e garantia do fabricante. Recomendação técnica Sempre substituir amortecedores em pares para garantir segurança estabilidade e desempenho equilibrado do veículo. Verificar especificamente se o veículo não possui barra estabilizadora e não é versão Locker ou cabine dupla.', 649.99, 444.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81zti-mkji9paghvyb24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F22898793143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
