INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893830554', 'Kit 3 und Neorub Pomada 12g', 'Kit 3 und Neorub Pomada 12g MODO DE USO: Passe uma camada fina do produto e massageie o local. Utilize até 3 vezes ao dia. FINALIDADE DE USO: Produto para o corpo. Neorub é uma pomada unguento de fácil aplicação composta por óleos essenciais, cânfora, mentol e eucalipto. CUIDADOS DE CONSERVAÇÃO: Conservar em temperatura ambiente. Proteger da luz e calor. ADVERTÊNCIAS: Para uso externo apenas. Mantenha fora do alcance de crianças. Não recomendado para crianças menores de 3 anos. Não utilize sobre a pele irritada ou lesada. Evitar contato com os olhos. Não utilize durante a gravidez. Em caso de sinais de intoxicação ou irritação, suspender o uso e procurar orientação médica. Não ingerir. COMPOSIÇÃO: ÁLcool cetoestearílico/ CETEARYL ALCOHOL, Vaselina sólida/ PETROLATUM, Parafina/ PARAFFINUM, Mentol/ MENTHOL, Cânfora/ CAMPHOR, Salicilato de Metila/ METHYL SALICYLATE, Óleo de eucalipto/ EUCALYPTUS GLOBULUS LEAF OIL, Óleo de cedro/ JUNIPERUS VIRGINIANA WOOD OIL, Óleo de noz moscada/ MYRISTICA FRAGRANS KERNEL OIL, Timol/ THYMOL, fragrância/ PARFUM, d- LIMONENE, EUGENOL, LINALOOL, fragrância de Terebentina/ OZONIZED TURPENTINE. Registro M.S.: Nº do Processo: 25351.385171/2017-19 – Cosmético Grau 2 Aut. Func.: 2.04.396-1', 25.98, 22.99, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rd3v-m7gt1sla0dtbfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22893830554', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
