INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397683992', 'Colchão Solteiro (88x188) D20 Preto Valencia Topázio Colchões', 'Desfrute de noites de sono revitalizantes com o Colchão Solteiro Valencia da respeitada marca Topázio Colchões. Com suas dimensões espaçosas de 12x88x188 centímetros, é ideal para proporcionar conforto individualizado. Sua espuma D20 oferece o suporte necessário para uma posição correta durante o repouso, assegurando um descanso revigorante para enfrentar as demandas do dia. O revestimento em poliéster na cor preta adiciona um toque de elegância ao ambiente, enquanto o tampo em poliéster proporciona uma superfície macia e agradável ao toque. Transforme seu quarto em um oásis de serenidade e conforto com o Colchão Solteiro Valencia da Topázio Colchões. Informações técnicas Cor Predominante do Produto: Preto Dimensões do produto: Altura: 12,00cm; Largura: 88,00cm; Comprimento: 188,00cm Dimensões do produto com embalagem: Altura: 12,00cm; Largura: 88,00cm; Comprimento: 188,00cm Marca: Topazio Colchões Conteúdo da embalagem: 1 Colchão Solteiro Modelo: Valencia Garantia: 3 Meses do Fabricante Peso: 3,80Kg Densidade: D20 Tamanho: Solteiro Tipo de Colchão: Espuma Atenção: As CORES e/ou GRAVURAS dos colchões poderão sofrer alterações na sua tonalidade ou tipologia na parte facial do produto dependendo da disponibilidade do fornecedor.', 319.9, 309.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-lvah5qr0cegqe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1060724397%2F19397683992', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
