INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393392121', 'Combo Segredos da Natureza Bosque do Aconchego', 'DESCRIÇÃO GERAL Novo Produto, Novo Conceito! O equilíbrio perfeito entre limpeza e bem-estar. O Limpador Multissuperfície Segredos da Natureza é o primeiro produto à base de álcool no mercado que foi desenvolvido para ser aplicado em + de 20 superfícies. Disponível em cinco fragrâncias exclusivas e óleos essenciais com o poder da aromaterapia, que proporcionam bem-estar e uma perfumação de até 30 horas. Esse lançamento da Coperalcool Bacfree apresenta a praticidade do sistema de gatilho anatômico. E diferente dos Limpadores Multiusos do mercado, não é necessário utilizar luvas para limpeza, pois ele não agride a pele. Surpreenda-se com as diferentes fragrâncias e características deste produto - agora você poderá aproveitar cada momento de bem-estar! A fragrância de Jasmim cria um ambiente aconchegante. Principais características do produto Perfumação por até 30 horas Brilho e acabamento impecável Prático e sem desperdício Secagem rápida Limpa mais de 20 superfícies Composição Água, Álcool Etílico, Tensoativo Aniônico, Tensoativo Catiônico, Emulsificante, Sequestrante, Conservante, Fragrância Oceano (frescor das águas) e Corante.', 37.8, 36.8, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/br-11134207-820lb-mqdv6oxumhhc4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F23393392121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092796107', 'Capa Case Capinha à Prova d''água Nautical para Samsung Galaxy S23 Ultra - Gshield', 'Use a melhor case para Samsung Galaxy S23 Ultra A Capa à Prova D''água Nautical da Gshield para Samsung é o acessório perfeito para quem adora aventuras e busca máxima proteção para o seu celular, seja na praia, no clube ou até mesmo no banho. Projetada para resistir a imersões de até 2 metros por 1 hora, ela garante segurança completa contra respingos e submersões acidentais, permitindo que você aproveite momentos ao ar livre ou em contato com a água sem preocupações. Feita em polipropileno de alta densidade, a capa é altamente resistente e não amarela com o tempo, preservando sua aparência e funcionalidade mesmo com o uso contínuo. Seu design é ajustado para se encaixar perfeitamente no seu aparelho, oferecendo proteção total sem comprometer a estética ou a experiência de uso. Além da resistência à água, a capa protege seu dispositivo contra impactos e riscos, mantendo a tela impecável e o celular em perfeito estado. Certificada com o padrão US Military, a Capa à Prova D''água Gshield combina tecnologia, durabilidade e estilo para te acompanhar em qualquer situação. ESPECIFICAÇÕES Material: Polipropileno de alta densidade - Não Amarela Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos à tela Certificações: Us Military Não apropriada para o uso no dia a dia COMPATIBILIDADE Samsung Galaxy S23 Ultra ITENS INCLUSOS 1x Capa protetora', 179.99, 179.99, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rcdo-ltcs3dk7ildx84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23092796107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
