INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498662544', 'GALINHA QUE TINHA MEDO DE MINHOCA!, A', 'GALINHA QUE TINHA MEDO DE MINHOCA!, A A galinha que tinha medo de minhocas! conta uma divertida história de uma galinha que tinha um medo inusitado de minhocas e tenta se esconder de todos, pois ela era uma galinha durona que não podia ter medo de nada. Para tentar se esconder de seus amigos, ela passa por situações embaraçosas. Nesta história, podemos ver, através de Cocó, que até os mais corajosos também podem ter medo de algo.. Informações Adicionais Autor: REIS, TIMOTEO Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: GALINHA QUE TINHA MEDO DE MINHOCA!, A Idioma: PORTUGUES Páginas: 16 Edição: 1 ISBN-13: 9788576713166 ISBN-10: 8576713160', 19.88, 15.11, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbnd-lpn8lfmm2nin29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22498662544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23291925927', 'DC - Boneca da Mulher Maravilha de 24cm - Colecionável', 'Descrição: O que você acha de ter um boneco detalhado do seu personagem preferido da DC? Escolha entre Mulher Maravilha, Flash, Superman, Batman e Coringa! Cada Boneco possui 3 pontos de articulação para você posá-los e movimentá-los da forma que você quiser! Cada boneco possui 24cm (9,5). Características: Marca: Sunny Brinquedos Referência: 3375 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 25,5 x 12,8 x 5cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Boneca da Mulher Maravilha Certificado Inmetro: 54763/21-003 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 89.99, 84.59, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7qvg0-ljref3t4b7mef3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23291925927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7744334665', 'Gel Decapante 1,250 Kg A380 Limpa Inox Avesta', 'GEL DECAPANTE 1,250 KG AMAZÔNIA O Gel Amazônia é utilizado no processo de tratamento de superfícies de equipamentos e tubulações em aço inoxidável da série 300. O Gel Amazônia é utilizado no processo de tratamento de superfícies de equipamentos e tubulações em aço inoxidável da série 300, tendo demonstrado excelente relação custo/benefício, comparado a outros processos. Benefícios alcançados com a sua utilização do produto: Eliminação da oxidação, blue color, escórias de soldas, recomposição do filme protetor de apassivação afetado pelo calor nas regiões de solda, eliminação dos contaminantes, garantia da qualidade visual e maior vida útil nos equipamentos novos ou já em operação. Características Aspecto: Gel Temperatura de aplicação: Ambiente Tempo de aplicação: 30 à 40 min Concentração da aplicação: in natura PH (concentrado / diluído): 0 à 1 Embalagem: pote com 1,250kg', 69.0, 69.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/c4fa8be9fb940b621b7120a15636eb78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F7744334665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
