INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4444342274', 'Inflador Compressor 110v Bomba Balões Bexigas 2 Bicos Festas elétrico', 'Design leve, inteligente, portátil e prático de utilizar, para festas e eventos, atividades promocionais e publicidade. - Potência de 600W, você consegue encher até 2 balões ao mesmo tempo em aproximadamente 2 SEGUNDOS! - Tem um compartimento para guardar a tomada. Possui dois modos de operação: - Swith on/off que aciona os dois bocais ao mesmo tempo. - Touch ON (a bomba liga ao encostar a bexiga no pino e desliga quando retira). - Seus bocais foram desenvolvidos para tornar a operação muito mais fácil, basta encaixar o balão e inflá-lo. - Bocal azul funciona individualmente ao ser pressionado. - Potente, de baixo ruído e pés em borracha, para se fixar melhor à superfície. - Ruído <95DB - Voltagem: 110V. Cor Disponível: APENAS ROSA. Dimensões: - Altura: 16 cm - Largura: 12 cm - Comprimento: 19,5 cm - Peso: 1243g - Comprimento do fio da tomada: 150 cm', 129.88, 78.9, NULL, 'Home & Living > Party Supplies > Balloons', 'https://cf.shopee.com.br/file/86e87e46ed5daebedc96b1b371690d63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F4444342274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
