INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19761903220', 'Bieleta Estabilizadora Jeep Compass 2017 Diant Le Ld Trw', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação JEEP COMPASS LIMITED 2.0 4X2 FLEX 16V AUT. 2017 COMPASS LONGITUDE 2.0 4X2 FLEX 16V AUT. 2017 COMPASS LONGITUDE 2.0 4X4 DIES. 16V AUT. 2017 COMPASS SPORT 2.0 4X2 FLEX 16V AUT. 2017 COMPASS TRAILHAWK 2.0 4X4 DIES. 16V AUT. 2017 Conteúdo Da Embalagem 1 Bieleta Tipo de Veículo para SUV''s e Caminhonetes Marca Criada há mais de 100 anos, a TRW produz inovações sempre com qualidade e referência, estabelecendo-se no mercado mundial com uma reputação de excelência, graças a segurança e durabilidade de seus produtos. A TRW oferece uma extraordinária gama de produtos e serviços reconhecidos globalmente. O Produto As bieletas são hastes que ligam a barra estabilizadora à suspensão do veículo, proporcionando melhor dirigibilidade e maior estabilidade para seu veículo. Barulhos e instabilidade na suspensão é um sinal de problemas nas bieletas. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses • Valor unitário • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 3322938344672 Código do Fabricante JTS1372 Posição Dianteiro Posição Dianteiro', 60.69, 60.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-111342