INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42215201033', 'Cooler para Notebook Acer Part Number DC28000JSF0', 'Cooler para Notebook Acer Part Number DC28000JSF0 | Interno ste é um Cooler bringIT compatível com o notebook Acer Part Number DC28000JSF0. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 4 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL194-AC-0003', 84.87, 28.42, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-825ax-mq5ywf517e2qd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F42215201033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22204999276', 'Filtro Cabine Ar Condicionado Grand Siena 2012 A 2018 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação GRAND SIENA ATTRAC. 1.4 EVO F.FLEX 8V 2012 até 2018 GRAND SIENA ESSEN. ITALIA DUAL. 1.6 FLEX 2015 GRAND SIENA ESSEN.SUBLIME 1.6 FLEX 2013 até 2018 GRAND SIENA ESSEN.SUBLIME DUAL. 1.6 FLEX 2014 até 2018 GRAND SIENA ESSENCE 1.6 FLEX 16V 2013 até 2018 GRAND SIENA ESSENCE DUAL. 1.6 FLEX 16V 2012 até 2018 GRAND SIENA ESSENCE ITALIA 1.6 FLEX 16V 2015 GRAND SIENA TETRAFUEL 1.4 EVO F. FLEX 8V 2013 até 2016 Conteúdo Da Embalagem 1 Filtro de Ar Condicionado Cor do Produto No Tipo de Veículo para Carros Marca Fundada em 1969, a Wega Motors Brasil possui sede própria em Itajaí/SC, com uma moderna instalação que produz uma ampla gama de produtos para o mercado de reparação automotiva na linha leve e pesada. A Wega Motors é certificada em Sistema de Gestão da Qualidade ISO9001 – Versão 2000 (pelo BVQI – Bureau Veritas Certification), certificação essa que abrange a fabricação e comercialização de filtros de óleo, ar e combustível, velas e acessórios. O Produto O filtro de cabine é essencial para proteger a vida dos ocupantes, pois com o passar do tempo, microrganismos e poluentes presentes no ar, passam a representar um verdadeiro risco à saúde dentro do veículo. O filtro de cabine tem a função de filtrar impurezas presentes fora do veículo e circula no sistema de ventilação, inibindo sujeiras, gases tóxicos, e demais poluentes que entram em contato com o interior do veículo, contribuindo para a proliferação de doenças respiratórias, como sinusite, rinite, gripes, etc. A importância do uso de filtro de cabine aumenta em automóveis com ar-condicionado, já que os vidros permanecem fechados na maior parte do tempo. O filtro de cabine está instalado em diversos veículos fabricados a partir dos anos 2000, independente de possuírem ar-condicionado ou não. Sua troca vai depender dos locais em que você circula, já que alguns possuem mais poluição. A recomendação é verificar o filtro de cabine a cada 20 mil km rodados. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 • Valor unitário EAN 7798159122546 Código do Fabricante AKX35323 >', 15.66, 15.66, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7r9bd-llts5mxfksop1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22204999276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20657310983', 'Jogo Vela de Ignição Ford Fiesta 1.0 8v 2006 a 2014 Green Ngk LTR7A10', 'Aplicação Ford Fiesta 1.0 8v 2006 a 2014 Conteúdo Da Embalagem 4 Velas de Ignição Tipo de Veículo para Carros Marca A NGK fabrica itens automotivos desde 1959 no Brasil. Revestimentos porcelanizados, cabos de ignição e velas, terminais supressivos e cerâmicas técnicas fazem parte da extensa gama de produtos da empresa. Além disso, a NGK é uma companhia certificada pela ISO/TS 16.949 e obedece as diversas regras de referências internacionais de qualidade. Os mais de 1300 funcionários da NGK do Brasil passam por um absoluto programa de treinamento e integração à filosofia de trabalho, no qual são estimulados a contribuir com propostas de melhoria contínua em benefício da organização e da sociedade. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses. • Valor referente ao jogo. • Imagem meramente ilustrativa. • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. Código do Fabricante LTR7A10 Combustível FLEX', 94.33, 94.33, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7r9ay-llut4cadug3pd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20657310983', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
