INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12597495356', 'Filtro Óleo Ford F-1000 F-4000 81 A 98 Mann-filter W934', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação F-1000 4Cil. Diesel - 1986 até 1998 F-4000 Diesel - 1981 até 1998 F-4000 Com Carcaça MANN-FILTER - 1980 até 1989 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para SUV''s e Caminhonetes Marca Com uma ampla e inovadora linha de produtos a MANN-FILTER, sempre primando um alto padrão de qualidade em seus produtos, atendendo assim a todas as exigências das montadoras. Contando com filtros de ar, óleo, combustível e cabine para todos os tipos de motores de veículos e máquinas. Importante Tempo de garantia - 3 meses. Imagem meramente ilustrativa. Valor unitário. Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. EAN 7893390600157 Código do Fabricante W934 >', 50.79, 50.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbli-llxnh11skac95b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F12597495356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497676975', 'KINGSMAN SERVIÇO SECRETO', 'KINGSMAN SERVIÇO SECRETO DO ESCRITOR DE KICK ASS, O DESENHISTA DE WATCHMEN E O DIRETOR DE X MEN PRIMEIRA CLASSE! Ao redor do globo, celebridades da cultura pop estão sendo abduzidas e ninguém sabe por quê. Jack London – superespião – está no caso. Mas Jack também tem seus próprios problemas uma irmã imprestável e seu filho fora de controle. O jovem Gary se meteu com companhias erradas e sua vida está indo pro buraco. Apenas Jack se encontra entre seu sobrinho e uma cela de cadeia. Mas vendo um pouco de si mesmo em Gary, Jack oferece ao garoto uma última chance de futuro – na escola de espiões. Fora de seu elemento, rodeado pelos melhores e mais inteligentes, será que sua esperteza adquirida nas ruas bastará para torná lo um agente secreto? Gary tem mesmo o que é preciso para ajudar seu tio a encontrar as celebridades e salvar o mundo? O conflito de classes se mistura com a guerra ao terrorismo, conforme Mark Millar e Dave Gibbons reinventam a espionagem para o século 21! Este volume de 172 páginas reúne as edições The Secret Service 1 6. Escrito por Mark Millar – roteirizado em parceria com Matthew Vaughn – e ilustrado por Dave Gibbons.. Informações Adicionais Autor: MILLAR, MARK Data Publicação: 01/01/1900 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: KINGSMAN SERVIÇO SECRETO Idioma: PORTUGUES Páginas: 172 Edição: 1 ISBN-13: 9788583680451 ISBN-10: 8583680450', 37.2, 37.2, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd5a-lv5szot1u9pq0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20497676975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699254803', 'CRIE SUA PRÓPRIA SORTE DESISTIR NÃO É OPÇÃO QUANDO SE TEM UM PROPÓSITO', 'CRIE SUA PRÓPRIA SORTE DESISTIR NÃO É OPÇÃO QUANDO SE TEM UM PROPÓSITO O que fazer quando os obstáculos em nosso caminho parecem insuperáveis e quando nossos maiores sonhos parecem inalcançáveis?De família humilde, Joyce Rodrigues deparou se muitas vezes, e desde muito cedo, com essas dúvidas, sempre com uma única certeza desistir não era uma opção.Ao acreditar em seu propósito, Joyce superou uma realidade de pobreza e poucas oportunidades e tornou se uma empresária de sucesso, referência para milhares de pessoas.Neste livro, você conhecerá a história de coragem e determinação da presidente do Grupo Mezzo e as valiosas lições que ela tirou dos múltiplos desafios que se colocaram em seu caminho. Quando você acredita no próprio potencial e é fiel aos valores em que acredita, o sucesso vem!. Informações Adicionais Autor: RODRIGUES, JOYCE Data Publicação: 20/05/2024 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: CRIE SUA PRÓPRIA SORTE DESISTIR NÃO É OPÇÃO QUANDO SE TEM UM PROPÓSITO Idioma: INDEFINIDO Páginas: 208 Edição: 1 ISBN-13: 9786553933163 ISBN-10: 6553933162', 59.9, 46.72, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/sg-11134201-7rd43-luf74e5kfxtz5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F21699254803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899335369', 'UNÇÃO DO ROMPEDOR', 'UNÇÃO DO ROMPEDOR Unção do Rompedor apresenta exemplos de superação e conquistas, bem como ensina a romper em todas as esferas e fases da vida. É uma obra indispensável a todos aqueles que anseiam por avanços genuínos.Com essa leitura você romperá e avançará em áreas de sua vida que estão estagnadas, bem como conquistará a excelência em tudo o que faz e vive, experimentando uma vida plena e feliz.. Informações Adicionais Autor: ARIANE, IRACET Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: UNÇÃO DO ROMPEDOR Idioma: INDEFINIDO Páginas: 144 Edição: 1 ISBN-13: 9786550474065 ISBN-10: 655047406X', 53.92, 53.92, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdwk-lygjmvpw3eh21d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F21899335369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194868811', 'Luva de Goleiro Poker Campo Training Basic Adulto Preto e Branco - Masculino', 'Segurança e aderência para defesas impecáveis! Luva de Goleiro Poker Campo Training Basic Adulto Preto e Branco - Masculino Parte superior do formulário Ficha Técnica: Cores: Preto com detalhes em prata e palma na cor branca Tamanho: 8, 9, 10 e 11 TBG (Training Basic Grip) Material: 4mm látex sintético e poliéster Tipo de Palma: BG (Basic Grip) Faixa etária: Adulto Indicado para: Futebol de campo Modelo da Cinta: Fixa com tira aderente para fixar uma na outra Classificação: Training Tipo de Punho: Elástico Completo Corte da Palma: Negativo Superfície Indicada: Grama Natural Gênero: Masculino Detalhes: Logotipo da marca estampado; design texturizado Obs: Atente-se ao escolher o tamanho desejado Já perdeu defesas por falta de aderência nas luvas? Isso pode comprometer seu desempenho em campo! Por que investir? A Luva de Goleiro Poker Campo Training Basic resolve esse problema com sua palma de 4mm em látex sintético, garantindo máxima fixação e segurança ao agarrar a bola. Seu corte negativo proporciona um encaixe ajustado e confortável, enquanto o punho elástico e a cinta aderente evitam movimentações indesejadas. Não deixe suas defesas ao acaso – escolha qualidade e garanta a sua agora! Conteúdo da embalagem: 1 par de Luva de Goleiro Poker Campo Training Basic Adulto Preto e Branco - MasculinoParte superior do formulário Parte superior do formulário', 89.99, 77.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-82630-mk9lmn33h98o2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F22194868811', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
