INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099649230', 'Camisa Palmeiras Vitor Roque 9 Alviverde Branca e Verde', 'VITOR ROQUE Vitor Roque é uma promessa do futebol brasileiro, com habilidade excepcional, velocidade e visão de jogo apuradas. Seu estilo é dinâmico, driblador e letal na finalização. Jovem, mas com maturidade em campo, já encanta torcedores com seu talento imbatível. Composição: 100% Poliéster Gola: Careca Cores predominantes: Branca e verde Modelo: Torcedor Origem: Nacional Gênero: Masculino Clube: Palmeiras Escudo: Estampado Manga: Curta Dimensões aproximadas (A x L): P: 67 x 51 cm M: 69 x 53 cm G: 71 x 55 cm GG: 73 x 57 cm', 119.9, 119.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/sg-11134201-7rd6k-m79zsaoqdkmhd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F19099649230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798483332', 'Kit 2x Vagisil Sabonete Líquido Íntimo Urin Protect 200 + 100g Grátis', 'O novo sabonete íntimo diário Vagisil Urin Protect foi desenvolvido especialmente para tratar a questão da incontinência urinária. O sabonete faz a higienização adequada depois que a urina entra em contato com a pele sensível da região íntima feminina. A limpeza acontece de forma a manter o pH da região e evita também a formação de maus odores. Modo de uso: Aplique o produto na palma de sua mão e lave a região genital externa. Enxágue abundantemente. Precauções: Em caso de irritação interrompa o uso e consulte seu médico. Mantenha-o fora do alcance de crianças. Aplicar somente nos órgãos genitais externos. Não use caso tenha hipersensibilidade aos componentes da fórmula. Evite contato com os olhos, caso isso ocorra, enxágue abundantemente. O uso excessivo de sabonete na região íntima pode ser uma fonte de irritação genital. Conservar em temperatura ambiente. Proteger da luz.', 79.9, 67.92, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ytrf1pqn7mef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1485857970%2F23798483332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
