INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257493236', 'ABSORVENTE INTERNO INTIMUS DISCRETO SUPER 8 UNIDADES', 'Não dá mais para escolher entre descrição, segurança e conforto quando falamos de absorção. O Absorvente Interno Intimus Discreto tem o ajuste perfeito a todos os movimentos, deixando-o confortável e protegido. Ah, e ainda possui uma barreira azul antivazamento, para reforçar ainda mais a segurança. Além disso é muito prático, sendo fácil de abrir a embalagem e fácil de colocar, já que possui cobertura dermoseda para maiores furos na inserção. O Absorvente Interno Intimus Discreto existe em três versões, que vai de fluxo leve até intenso. Essa é a versão super, destinada a fluxo intenso. Experimente e confira!', 12.99, 12.99, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-825zu-mm7isjuknwg53b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1765202114%2F58257493236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
